sources.styles/scrollbars.css:
/* Native scrolling and hit testing, including OS overlay-scrollbar behavior.
   The installed Codex app uses a transparent track and a border-tone hover thumb. */
:root {
  scrollbar-color: var(--border-heavy) transparent;
}
* {
  scrollbar-width: thin;
}
.scrollbar-on-hover::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
.scrollbar-on-hover::-webkit-scrollbar-track,
.scrollbar-on-hover::-webkit-scrollbar-corner {
  background: transparent;
}
.scrollbar-on-hover::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 8px;
  background: var(--border-heavy);
  background-clip: padding-box;
}
@media (hover: hover) and (forced-colors: none) {
  .scrollbar-on-hover {
    scrollbar-color: transparent transparent;
    transition: scrollbar-color 150ms ease;
  }
  .scrollbar-on-hover:is(:hover, :focus-within) {
    scrollbar-color: var(--border-heavy) transparent;
  }
  .scrollbar-on-hover::-webkit-scrollbar-thumb {
    background-color: transparent;
  }
  .scrollbar-on-hover:is(:hover, :focus-within)::-webkit-scrollbar-thumb {
    background-color: var(--border-heavy);
  }
}
@media (prefers-reduced-motion: reduce) {
  .scrollbar-on-hover {
    transition: none;
  }
}
@media (forced-colors: active) {
  :root,
  .scrollbar-on-hover {
    scrollbar-color: auto;
  }
  * {
    scrollbar-width: auto;
  }
}

sources.styles/tokens.css:
/*
 * Semantic tokens. Colors are derived at runtime from the selected theme
 * (see features/theme/theme.ts); these values are the default dark theme,
 * used only until the first theme is applied. Components use these names
 * only, never raw colors.
 *
 * Ceramic: glaze, chip, composer, and primary-glaze are gradients; their
 * matching *-shadow tokens carry the top edge, hairline ring, and drop.
 */
:root {
  color-scheme: dark;
  --project-gray: #5e5e5e;
  --project-blue: #356fcd;
  --project-green: #2f7555;
  --project-orange: #b96738;
  --project-pink: #b24287;
  --project-purple: #674ac2;
  --on-project: #ffffff;
  --scan-light: #ffffff;
  --scan-dark: #000000;
  --surface: #1a1a1d;
  --surface-under: #141416;
  --elevated: #242427;
  --control: #2f2f32;
  --text: #ededf0;
  --text-secondary: #b0b0b3;
  --text-tertiary: #828285;
  --activity-skill: var(--project-purple);
  --activity-search: var(--project-blue);
  --activity-edit: var(--project-orange);
  --user-message: #303033;
  --border: rgb(237 237 240 / 0.084);
  --border-heavy: rgb(237 237 240 / 0.156);
  --hover: rgb(237 237 240 / 0.068);
  --selected: rgb(237 237 240 / 0.1);
  --secondary: rgb(237 237 240 / 0.052);
  --secondary-hover: rgb(237 237 240 / 0.094);
  --primary: #ededf0;
  --primary-hover: #cfcfd2;
  --on-primary: #1a1a1d;
  --accent: #ededf0;
  --accent-soft: #464649;
  --accent-text: #ededf0;
  --on-accent: #000000;
  --error: #ff7b72;
  --success: #5fd47f;
  --warning: #e2b85a;
  --link: #ededf0;
  --link-underline: rgb(237 237 240 / 0.4);
  --scrim: rgb(0 0 0 / 0.5);
  --shadow: 0 12px 32px rgb(0 0 0 / 0.45), 0 2px 6px rgb(0 0 0 / 0.25);
  --card-shadow: 0 2px 8px rgb(0 0 0 / 0.2), 0 8px 24px rgb(0 0 0 / 0.15);
  --bubble: #28282b;
  --code-bg: rgb(237 237 240 / 0.08);
  --wordmark-muted: #7d7d80;
  --glaze: linear-gradient(180deg, #262629 0%, #202023 100%);
  --glaze-shadow:
    inset 0 1px 0 rgb(237 237 240 / 0.07), 0 0 0 1px rgb(237 237 240 / 0.08),
    0 1px 3px rgb(0 0 0 / 0.35);
  --chip: linear-gradient(180deg, #2b2b2e 0%, #232326 100%);
  --chip-border: rgb(237 237 240 / 0.09);
  --chip-shadow: inset 0 1px 0 rgb(237 237 240 / 0.07), 0 1px 1px rgb(0 0 0 / 0.2);
  --composer: linear-gradient(180deg, #222225 0%, #1d1d20 100%);
  --composer-shadow:
    inset 0 1px 0 rgb(237 237 240 / 0.07), 0 0 0 1px rgb(237 237 240 / 0.08),
    0 10px 28px rgb(0 0 0 / 0.35), 0 2px 5px rgb(0 0 0 / 0.25);
  --well: #121214;
  --well-shadow: inset 0 1px 2px rgb(0 0 0 / 0.7);
  --primary-glaze: linear-gradient(180deg, #ffffff 0%, #e8e8eb 55%, #d3d3d6 100%);
  --primary-shadow:
    inset 0 1px 0 #ffffff, inset 0 -2px 3px rgb(0 0 0 / 0.12), 0 1px 2px rgb(0 0 0 / 0.5),
    0 3px 8px rgb(0 0 0 / 0.35);
  --primary-sheen: linear-gradient(180deg, rgb(255 255 255 / 0.65) 0%, rgb(255 255 255 / 0) 100%);
  --syntax-keyword: #ededf0;
  --syntax-keyword-weight: 400;
  --syntax-string: #5fd47f;
  --syntax-comment: #828285;
  --syntax-punctuation: #b0b0b3;

  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono:
    ui-monospace, 'SFMono-Regular', 'SF Mono', Menlo, Consolas, 'Liberation Mono', monospace;
  --chat-font-size: 14px;
  --chat-line-height: calc(var(--chat-font-size) * 1.625);
  --chat-code-font-size: 13px;
  --sidebar-width: 300px;
  --toolbar-height: 40px;
  --row-height: 36px;
  --thread-width: 768px;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --duration-fast: 120ms;
  --duration-medium: 200ms;
  --duration-slow: 240ms;
}

:root[data-platform] {
  --row-height: 30px;
}

sources.styles/globals.css:
@import 'tailwindcss' source(none);
@import './tokens.css';
@import './scrollbars.css';
@source '../';

@theme inline {
  --color-surface: var(--surface);
  --color-text: var(--text);
  --color-muted: var(--text-secondary);
  --color-border: var(--border);
  --color-accent: var(--accent);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}
html,
body,
#root {
  height: 100%;
}
body {
  margin: 0;
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
button,
input {
  font: inherit;
  color: inherit;
}
button {
  cursor: pointer;
}
:root[data-platform] button {
  cursor: default;
}
button:disabled {
  cursor: default;
  opacity: 0.45;
}
:focus,
:focus-visible {
  outline: none;
}
h1,
h2,
p,
dl,
dd {
  margin: 0;
}
code {
  font-family: var(--font-mono);
  font-size: 12px;
}
svg {
  flex-shrink: 0;
}
.truncate {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.truncate-fade {
  min-width: 0;
  overflow: hidden;
  padding-right: 24px;
  white-space: nowrap;
  /* The trailing space keeps short labels clear of the fade. */
  mask-image: linear-gradient(to right, var(--text) calc(100% - 24px), transparent);
}
.text-error {
  color: var(--error);
}

/* Shell */
.app-shell {
  display: grid;
  grid-template-columns: clamp(200px, var(--sidebar-width), min(480px, calc(100vw - 360px))) minmax(
      0,
      1fr
    );
  height: 100dvh;
  background: var(--surface-under);
}
.sidebar {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  --row-height: 32px;
  background: var(--surface-under);
}
.sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
  height: var(--toolbar-height);
  padding: 0 8px;
  -webkit-app-region: drag;
}
.sidebar-header button {
  -webkit-app-region: no-drag;
}
.sidebar-brand {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text-tertiary);
}
.sidebar-brand-icon {
  display: block;
  flex: none;
  width: 24px;
  height: 24px;
  object-fit: contain;
}
.sidebar-wordmark {
  display: block;
  width: 96px;
  height: 16.4px;
  min-width: 0;
  flex-shrink: 1;
}
/* Native macOS controls occupy the titlebar's left edge outside fullscreen. */
:root[data-platform='darwin']:not([data-fullscreen='true']) .sidebar-header {
  padding-left: 88px;
}
.toolbar-brand {
  display: inline-flex;
  align-items: center;
  flex: none;
}
.main-shell {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: var(--surface);
  border-left: 0.5px solid var(--border);
}
.toolbar {
  anchor-name: --chat-toolbar;
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 8px;
  height: var(--toolbar-height);
  padding: 0 20px;
  font-size: 13px;
  border-bottom: 1px solid var(--border);
}
:root[data-platform] .toolbar {
  -webkit-app-region: drag;
}
:root[data-platform] .toolbar button {
  -webkit-app-region: no-drag;
}
.toolbar-title {
  margin: 0;
  font-size: 13px;
  font-weight: 500;
}
.toolbar-project {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 30%;
  color: var(--text-secondary);
}
.toolbar-separator {
  color: var(--text-tertiary);
  margin-inline: 2px;
}
.toolbar-status {
  margin-left: auto;
  font-size: 12px;
  color: var(--text-tertiary);
  animation: appear 150ms 1s both;
}
.main {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  overflow-y: auto;
  min-width: 0;
}
.workspace-body {
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
  position: relative;
}
.chat-column {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.workspace-loading {
  width: 400px;
  max-width: 50%;
  padding: 24px;
  color: var(--text-tertiary);
}
.main:focus {
  outline: none;
}
.toolbar .sidebar-toggle,
.sidebar-scrim {
  display: none;
}
.skip-link {
  position: fixed;
  top: -60px;
  left: 12px;
  z-index: 50;
  padding: 8px 12px;
  border-radius: 10px;
  background: var(--primary);
  color: var(--on-primary);
}
.skip-link:focus {
  top: 12px;
}

/* Sidebar */
.shortcut-key {
  flex-shrink: 0;
  padding: 3px 7px;
  border: 1px solid var(--border);
  border-radius: 5px;
  color: var(--text-secondary);
  font: inherit;
  white-space: nowrap;
}
.shortcuts-description {
  margin-bottom: 24px;
  color: var(--text-secondary);
  font-size: 14px;
}
.nav-row {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: var(--row-height);
  padding: 0 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 13.5px;
  text-align: left;
}
.nav-row[aria-current] {
  background: var(--selected);
  color: var(--text);
}
.sidebar-nav,
.nav-group,
.session-list {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.nav-group {
  margin-top: 12px;
}
.sidebar-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 28px;
  padding: 0 2px 0 8px;
  color: var(--text-tertiary);
  font-size: 12px;
  font-weight: 500;
}
.project-heading {
  display: flex;
  align-items: center;
}
.project-heading > .project-row {
  flex: 1;
  min-width: 0;
}
.project-close,
.project-new-chat {
  flex-shrink: 0;
}
.project-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: var(--row-height);
  padding: 0 8px;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 400;
}
.project-row > svg {
  color: var(--text-secondary);
}
.project-row > span {
  flex: 1;
}
.project-folder .project-icon {
  flex: none;
  width: 16px;
  height: 16px;
  font-size: 12px;
  border-radius: 4px;
}
.session-list {
  padding-block: 0 14px;
}
/* Project and thread titles share the design's text column. */
.session-row,
.session-more {
  padding-left: 32px;
  font-size: 13px;
}
.session-row > .truncate-fade {
  flex: 1;
}
.session-row {
  position: relative;
}
.session-row > .session-kind {
  display: inline-flex;
  flex: none;
  color: var(--text-tertiary);
}
.session-activity {
  flex: none;
  width: 10px;
  height: 10px;
  border: 1.5px solid var(--border-heavy);
  border-top-color: var(--text-secondary);
  border-right-color: var(--text-secondary);
  border-radius: 50%;
  animation: spin 900ms linear infinite;
}
.session-unread {
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}
.session-more {
  color: var(--text-tertiary);
}
.sidebar-note {
  padding: 6px 8px;
  color: var(--text-tertiary);
  font-size: 12px;
}
.session-list .sidebar-note {
  padding-left: 32px;
}
.sidebar-note .button {
  margin-top: 8px;
}
.sidebar-footer {
  margin-top: auto;
  padding-top: 8px;
}
.sidebar-footer-row {
  display: flex;
  align-items: center;
  gap: 2px;
}
.sidebar-footer-row > .button {
  color: var(--text-secondary);
}

/* Workspace */
.empty-state {
  width: min(100%, 520px);
  margin: auto;
  padding: 48px 24px 16vh;
  text-align: center;
}
.empty-state h1 {
  overflow-wrap: anywhere;
}
.empty-state > p {
  margin-top: 10px;
  color: var(--text-secondary);
  font-size: 14.5px;
}
.empty-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  margin-top: 24px;
}
.empty-error {
  color: var(--error);
  font-size: 13px;
}
.empty-path {
  color: var(--text-tertiary);
  overflow-wrap: anywhere;
}
.project-form {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  width: 100%;
}
.project-input {
  display: flex;
  flex: 1;
  align-items: center;
  min-width: 0;
  height: 36px;
  padding: 0 4px 0 12px;
  border: 1px solid var(--border-heavy);
  border-radius: 10px;
  background: var(--control);
}
.project-input:focus-within {
  border-color: var(--accent);
}
.project-input input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  background: transparent;
  font-family: var(--font-mono);
  font-size: 13px;
}
.project-input input:focus-visible {
  outline: none;
}
.project-input input::placeholder {
  color: var(--text-tertiary);
}
.project-form .button-primary {
  height: 36px;
}
/* Floats under the path field in the top layer, so it covers content instead of moving it. */
.project-input[data-suggesting] {
  anchor-name: --project-folders;
}
.project-folders {
  position: fixed;
  position-anchor: --project-folders;
  inset: auto;
  top: anchor(bottom);
  left: anchor(left);
  width: anchor-size(width);
  height: calc(var(--rows) * 30px + 10px);
  margin: 4px 0 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 4px;
  border: 1px solid var(--border-heavy);
  border-radius: 10px;
  background: var(--elevated);
  box-shadow: var(--shadow);
  color: var(--text);
  text-align: left;
  position-try-fallbacks: flip-block;
}
.project-folders[data-stale] [role='option'] {
  opacity: 0.5;
}
.project-folders [role='option'] {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 30px;
  padding: 0 8px;
  border-radius: 6px;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 12.5px;
  cursor: pointer;
}
.project-folders [role='option'] > svg {
  flex: none;
  color: var(--text-tertiary);
}
.project-folders [role='option'] > span {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.project-folders [aria-selected='true'] {
  background: var(--hover);
  color: var(--text);
}
.project-folders mark {
  background: transparent;
  color: var(--text);
  font-weight: 600;
}
.project-folders p {
  padding: 6px 8px;
  color: var(--text-tertiary);
  font-size: 12px;
}
.field-error {
  flex-basis: 100%;
  color: var(--error);
  font-size: 13px;
  text-align: left;
}
.field-error:empty {
  display: none;
}
.session-view {
  width: min(100%, 720px);
  margin: 0 auto;
  padding: 40px 24px;
}
.session-view h1 {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
  overflow-wrap: anywhere;
}
.session-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 32px;
  font-size: 13px;
}
.session-meta dt {
  color: var(--text-tertiary);
  font-size: 12px;
}
.session-meta dd {
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}
.session-note {
  margin-top: 32px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
  color: var(--text-tertiary);
  font-size: 13px;
}

/* Settings */
.settings-page {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: min(100%, 720px);
  margin: 0 auto;
  padding: 24px 24px 64px;
}
.settings-page h1 {
  margin-bottom: 8px;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.settings-group {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--elevated);
}
.settings-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 52px;
  padding: 10px 16px;
}
.settings-row + .settings-row {
  border-top: 1px solid var(--border);
}
.settings-group-header h2 {
  font-size: 13px;
  font-weight: 600;
}
.settings-chat-preview {
  padding: 16px;
  border-top: 1px solid var(--border);
  font-size: var(--chat-font-size);
  line-height: var(--chat-line-height);
}
.settings-label {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  font-size: 13px;
}
.settings-label p {
  color: var(--text-secondary);
  font-size: 12px;
}
.settings-label code {
  color: var(--text-tertiary);
  overflow-wrap: anywhere;
}
.settings-control {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

/* Project settings */
.settings-page[data-section='projects'] {
  width: min(100%, 900px);
  gap: 24px;
}
.projects-settings-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.projects-settings-header > div {
  min-width: 0;
}
.projects-settings-header p {
  color: var(--text-secondary);
  font-size: 14px;
}
.projects-search {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 16px;
  border-radius: 8px;
  background: var(--secondary);
  color: var(--text-tertiary);
}
.projects-search > svg {
  flex-shrink: 0;
}
.projects-search input {
  min-width: 0;
  width: 100%;
  height: 44px;
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--text);
  box-shadow: none;
  outline: none;
  font-size: 14px;
}
.projects-search input::placeholder {
  color: var(--text-tertiary);
  opacity: 1;
}
.projects-settings-list {
  margin: 0;
  padding: 0 16px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--secondary);
  list-style: none;
}
.projects-settings-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.projects-settings-row + .projects-settings-row {
  border-top: 1px solid var(--border);
}
.project-settings-link {
  display: flex;
  align-items: center;
  flex: 1;
  gap: 10px;
  min-width: 0;
  min-height: 56px;
  padding: 10px 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text);
  text-align: left;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
}
.project-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  overflow: hidden;
  border-radius: 5px;
  background: var(--project-gray);
  color: var(--on-project);
  box-shadow: inset 0 0 0 1px var(--border-heavy);
  font-size: 13px;
  font-weight: 500;
  line-height: 1;
}
.project-icon[data-color='blue'] {
  background: var(--project-blue);
}
.project-icon[data-color='green'] {
  background: var(--project-green);
}
.project-icon[data-color='orange'] {
  background: var(--project-orange);
}
.project-icon[data-color='pink'] {
  background: var(--project-pink);
}
.project-icon[data-color='purple'] {
  background: var(--project-purple);
}
.project-icon[data-image] {
  background: transparent;
  box-shadow: none;
}
.project-icon img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.project-actions {
  position: relative;
  flex-shrink: 0;
}
.project-actions-menu {
  position: absolute;
  z-index: 10;
  top: calc(100% + 4px);
  right: 0;
  display: flex;
  flex-direction: column;
  width: 176px;
  padding: 4px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--elevated);
  box-shadow: var(--shadow);
}
.project-actions-menu[data-above='true'] {
  top: auto;
  bottom: calc(100% + 4px);
}
.project-actions-menu button {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 10px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--text);
  text-align: left;
  font-size: 13px;
  cursor: pointer;
}
.project-actions-menu button:focus-visible {
  background: var(--selected);
}
.project-actions-menu button svg {
  flex: none;
  color: var(--text-secondary);
}
.project-actions-menu button[data-danger],
.project-actions-menu button[data-danger] svg {
  color: var(--error);
}
.projects-notice,
.projects-empty {
  color: var(--text-secondary);
  font-size: 14px;
}
.projects-notice {
  display: flex;
  align-items: center;
  gap: 12px;
}
.projects-empty {
  padding: 36px 16px;
  text-align: center;
}
.projects-empty .button {
  margin-top: 12px;
}
.dialog {
  width: min(440px, calc(100vw - 32px));
  max-width: none;
  max-height: calc(100dvh - 32px);
  margin: auto;
  padding: 0;
  border: 1px solid var(--border-heavy);
  border-radius: 14px;
  background: var(--elevated);
  color: var(--text);
  box-shadow: var(--shadow);
}
.dialog::backdrop {
  background: var(--scrim);
}
.dialog-content {
  padding: 20px;
}
.dialog-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}
.dialog-header h2 {
  font-size: 16px;
  font-weight: 600;
}
.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
.project-dialog-description {
  margin-bottom: 16px;
  font-size: 13px;
  color: var(--text-secondary);
}
.dialog .project-form {
  width: 100%;
}
.project-editor {
  display: flex;
  flex-direction: column;
  gap: 20px;
  font-size: 13px;
}
.project-instructions-dialog {
  width: min(600px, calc(100vw - 32px));
}
.project-instructions {
  display: flex;
  flex-direction: column;
  gap: 12px;
  font-size: 13px;
}
.project-instructions-description,
.project-instructions-hint {
  margin: 0;
  color: var(--text-secondary);
  line-height: 1.5;
}
.project-instructions-hint {
  color: var(--text-tertiary);
  font-size: 12px;
}
.project-instructions textarea {
  width: 100%;
  min-height: 260px;
  max-height: calc(100dvh - 300px);
  padding: 10px 12px;
  border: 1px solid var(--border-heavy);
  border-radius: 8px;
  background: var(--control);
  color: var(--text);
  font: inherit;
  font-size: 13px;
  line-height: 1.55;
  resize: vertical;
}
.project-instructions textarea::placeholder {
  color: var(--text-tertiary);
}
.project-instructions textarea:focus-visible {
  outline: 2px solid var(--border-heavy);
  outline-offset: 1px;
}
.project-instructions-error {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 120px;
}
.project-editor-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.project-editor-field input {
  width: 100%;
  height: 36px;
  padding: 0 10px;
  border: 1px solid var(--border-heavy);
  border-radius: 8px;
  background: var(--control);
}
.project-editor-icon {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.project-editor-icon > .project-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  font-size: 26px;
}
.project-editor-icon p,
.project-editor-url p {
  margin-top: 6px;
  color: var(--text-tertiary);
  font-size: 12px;
}
.project-editor-url {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.project-editor-url-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.project-color-field {
  border: 0;
  padding: 0;
  margin: 0;
}
.project-color-field legend {
  margin-bottom: 8px;
}
.project-colors {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.project-color-option {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 8px;
}
.project-color-option input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  appearance: none;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: inherit;
  background: transparent;
  cursor: pointer;
}
.project-color-option input:checked {
  background: var(--selected);
}
.project-color-option > .project-icon {
  pointer-events: none;
}
.project-editor-path {
  color: var(--text-tertiary);
  font-size: 12px;
  overflow-wrap: anywhere;
}
@media (hover: hover) {
  .project-settings-link:hover,
  .project-actions-menu button:hover:not(:disabled) {
    background: var(--hover);
  }
  .project-actions-menu button[data-danger]:hover:not(:disabled) {
    background: color-mix(in srgb, var(--error) 12%, transparent);
  }
}
@media (pointer: coarse) {
  .project-actions > .button,
  .dialog-header > .button {
    width: 44px;
    height: 44px;
  }
  .project-actions-menu button {
    min-height: 44px;
  }
  .project-color-option {
    width: 44px;
    height: 44px;
  }
}
@media (max-width: 720px) {
  .projects-settings-header {
    align-items: flex-start;
    flex-wrap: wrap;
  }
  .projects-search input,
  .project-editor-field input {
    font-size: 16px;
  }
  .project-instructions textarea {
    font-size: 16px;
  }
  .project-settings-link {
    min-height: 56px;
    font-size: 16px;
  }
}

/* Controls */
.button {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 32px;
  padding: 0 14px;
  border: 0;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  transition:
    background-color var(--duration-fast) var(--ease-out),
    color var(--duration-fast) var(--ease-out),
    scale var(--duration-fast) var(--ease-out);
}
/* Anything you press is glazed ceramic; surfaces stay flat. */
.button-primary {
  background: var(--primary-glaze);
  box-shadow: var(--primary-shadow);
  color: var(--on-primary);
  font-weight: 600;
}
.button-secondary {
  background: var(--chip);
  box-shadow:
    var(--chip-shadow),
    inset 0 0 0 1px var(--chip-border);
  color: var(--text);
}
.button-ghost {
  background: transparent;
  color: var(--text-secondary);
}
.button-sm {
  height: 28px;
  padding: 0 10px;
  font-size: 12px;
}
.button-icon {
  width: 28px;
  height: 28px;
  padding: 0;
  border-radius: 7px;
}
.segmented {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  gap: 2px;
  padding: 2px;
  border-radius: 9px;
  background: var(--well);
  box-shadow: var(--well-shadow);
}
.segmented-thumb {
  position: absolute;
  top: 2px;
  bottom: 2px;
  left: 0;
  z-index: -1;
  width: var(--thumb-width);
  border-radius: 7px;
  background: var(--glaze);
  box-shadow: var(--glaze-shadow);
  transform: translateX(var(--thumb-x));
  pointer-events: none;
}
.segmented:not([data-placed]) .segmented-thumb {
  display: none;
}
.segmented button {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 500;
  transition: color var(--duration-fast) var(--ease-out);
}
.segmented button[aria-checked='true'],
.segmented button:focus-visible {
  color: var(--text);
}
.segmented button:focus-visible {
  box-shadow: inset 0 0 0 1px var(--border-heavy);
}
.segmented-badge {
  padding: 0 5px;
  border-radius: 4px;
  background: var(--secondary);
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}
.select {
  position: relative;
}
.select-trigger,
.color-field {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  border: 1px solid var(--chip-border);
  border-radius: 9px;
  background: var(--chip);
  box-shadow: var(--chip-shadow);
  font-size: 13px;
}
.select-trigger {
  width: 220px;
  padding: 0 10px 0 5px;
  text-align: left;
}
.select-chevron {
  margin-left: auto;
  color: var(--text-tertiary);
  transition: rotate var(--duration-medium) var(--ease-out);
}
.select-trigger[aria-expanded='true'] .select-chevron {
  rotate: 180deg;
}
.select-menu {
  transform-origin: top right;
}
.select-menu[data-placement='top'] {
  transform-origin: bottom right;
}
.select-menu {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 20;
  width: 240px;
  margin: 0;
  padding: 5px;
  border: 1px solid var(--border-heavy);
  border-radius: 12px;
  background: var(--elevated);
  box-shadow: var(--shadow);
}
.select-options {
  position: relative;
  max-height: min(320px, 45dvh);
  overflow-y: auto;
  overscroll-behavior: contain;
  margin: 0;
  padding: 0;
  list-style: none;
}
.select-menu[data-placement='top'] {
  top: auto;
  bottom: calc(100% + 4px);
}
.select-options:focus-visible {
  outline: none;
}
.select[data-floating] .select-trigger[aria-expanded='true'] {
  anchor-name: --select-floating;
}
.select-menu[popover] {
  position: fixed;
  position-anchor: --select-floating;
  inset: auto;
  top: anchor(bottom);
  right: anchor(right);
  margin: 4px 0 0;
  overflow: visible;
  color: var(--text);
  position-try-fallbacks: flip-block;
}
.select-menu[popover][data-placement='top'] {
  top: auto;
  bottom: anchor(top);
  margin: 0 0 4px;
}
.select-menu li {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 8px 0 5px;
  border-radius: 6px;
  font-size: 13px;
}
.select-menu li[data-active='true'] {
  background: var(--hover);
}
.select-check {
  margin-left: auto;
  color: var(--text-secondary);
}
.theme-option {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.theme-chip {
  display: grid;
  flex-shrink: 0;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid;
  border-radius: 50%;
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
}
.color-field {
  padding: 0 8px 0 4px;
}
.color-field:focus-within {
  border-color: var(--accent);
}
.color-field input[type='color'] {
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  background: none;
}
.color-field input[type='color']::-webkit-color-swatch-wrapper {
  padding: 0;
}
.color-field input[type='color']::-webkit-color-swatch {
  border: 1px solid var(--border-heavy);
  border-radius: 50%;
}
.color-field input[type='color']::-moz-color-swatch {
  border: 1px solid var(--border-heavy);
  border-radius: 50%;
}
.color-field input[type='text'] {
  width: 64px;
  border: 0;
  background: transparent;
  font-family: var(--font-mono);
  font-size: 12px;
}
.color-field input:focus-visible {
  outline: none;
}
.contrast-field {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 220px;
}
.contrast-field input {
  flex: 1;
  accent-color: var(--accent);
}
.contrast-field output {
  width: 24px;
  color: var(--text-secondary);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}
.chat-font-size-field output {
  width: 4ch;
  flex-shrink: 0;
}

@media (hover: hover) {
  .nav-row:hover:not([aria-current]):not(:disabled),
  .button-ghost:hover:not(:disabled) {
    background: var(--hover);
    color: var(--text);
  }
  .button-primary:hover:not(:disabled) {
    background: var(--primary-hover);
  }
  .button-secondary:hover:not(:disabled) {
    background: var(--secondary-hover);
  }
  .segmented button:hover:not([aria-checked='true']) {
    color: var(--text);
  }
  .sidebar-heading .button,
  .project-heading .project-close {
    opacity: 0;
  }
  .sidebar-heading:hover .button,
  .project-heading:hover .button,
  .sidebar-heading .button:focus-visible,
  .project-heading .button:focus-visible {
    opacity: 1;
  }
}

@media (min-width: 721px) {
  .app-shell[data-sidebar-collapsed='true'] {
    grid-template-columns: minmax(0, 1fr);
  }
  .app-shell[data-sidebar-collapsed='true'] .sidebar {
    display: none;
  }
  /* Native controls remain at the window's left edge when the sidebar hides. */
  :root[data-platform='darwin']:not([data-fullscreen='true'])
    .app-shell[data-sidebar-collapsed='true']
    .toolbar {
    padding-left: 96px;
  }
}

@media (pointer: coarse) {
  .nav-row,
  .select-menu li {
    min-height: 44px;
  }
  .button,
  .select-trigger,
  .color-field,
  .project-input,
  .project-form .button-primary {
    min-height: 44px;
  }
  .button-icon {
    width: 44px;
  }
  input {
    font-size: 16px !important;
  }
}

@media (max-width: 720px) {
  .app-shell {
    grid-template-columns: minmax(0, 1fr);
  }
  .sidebar {
    position: fixed;
    inset: 0 auto 0 0;
    z-index: 30;
    width: min(300px, 85vw);
    visibility: hidden;
    transform: translateX(-100%);
    transition:
      transform 200ms ease-out,
      visibility 200ms;
  }
  .app-shell[data-sidebar-open='true'] .sidebar {
    visibility: visible;
    transform: none;
  }
  .app-shell[data-sidebar-open='true'] .sidebar-scrim {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 25;
    background: var(--scrim);
  }
  .main-shell {
    border-left: 0;
  }
  .toolbar {
    padding-left: 8px;
  }
  .toolbar .sidebar-toggle {
    display: inline-flex;
  }
  .desktop-sidebar-toggle {
    display: none;
  }
  .toolbar-project {
    max-width: 35%;
  }
  /* A thread's own title needs the room more than its project name. */
  .toolbar-project:has(~ .session-title),
  .toolbar-separator:has(~ .session-title) {
    display: none;
  }
  .settings-page,
  .session-view {
    padding-inline: 16px;
  }
  .settings-row {
    flex-wrap: wrap;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sidebar,
  .button,
  .segmented button,
  .select-chevron {
    transition: none;
  }
  .toolbar-status,
  .session-activity,
  .spin {
    animation: none;
  }
}

.spin {
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to {
    rotate: 360deg;
  }
}

@keyframes appear {
  from {
    opacity: 0;
  }
}

/* Motion: only opacity and transforms, so nothing here triggers layout. */
@media (prefers-reduced-motion: no-preference) {
  .button:not(:disabled):active,
  .segmented button:active {
    scale: 0.97;
  }
  .disclosure-chevron,
  .activity-tray-chevron,
  .session-details-chevron {
    transition: transform var(--duration-medium) var(--ease-out);
  }
  /* Menus and popovers settle in from their trigger; closing stays instant. */
  [popover]:popover-open,
  .select-menu {
    transition:
      opacity var(--duration-fast) var(--ease-out),
      scale var(--duration-fast) var(--ease-out);
  }
  dialog[open],
  dialog[open]::backdrop {
    transition:
      opacity var(--duration-slow) var(--ease-out),
      scale var(--duration-slow) var(--ease-out);
  }
}
@starting-style {
  [popover]:popover-open,
  .select-menu {
    opacity: 0;
    scale: 0.97;
  }
  dialog[open] {
    opacity: 0;
    scale: 0.96;
  }
  dialog[open]::backdrop {
    opacity: 0;
  }
}

/* Projects and conversation */
.sidebar-actions {
  margin-bottom: 16px;
}
.sidebar-actions .nav-row {
  color: var(--text);
}
.project-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.project-group {
  margin-top: 4px;
}
.chat {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}
.chat-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-anchor: none;
}
.chat-transcript {
  display: flex;
  flex-direction: column;
  gap: 24px;
  width: min(100%, var(--thread-width));
  margin: 0 auto;
  padding: 32px 24px 8px;
}
/* The hero shares the composer's column, so the starters line up with it. */
.chat-empty {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(100%, var(--thread-width));
  margin: 0 auto;
  padding: 0 24px 28px;
  text-align: center;
}
.hero-art {
  display: block;
  width: 176px;
  height: 176px;
  margin: 0 auto 4px;
  user-select: none;
}
.chat-empty h2,
.empty-state h1 {
  font-size: 30px;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.02em;
}
.chat-empty > p {
  margin-top: 10px;
  color: var(--text-secondary);
  font-size: 14.5px;
}
.starters {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  width: 100%;
  margin-top: 28px;
}
.starter {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  min-height: 104px;
  padding: 14px;
  border: 0;
  border-radius: 14px;
  background: var(--glaze);
  box-shadow: var(--glaze-shadow);
  color: var(--text);
  font-size: 13.5px;
  font-weight: 500;
  line-height: 1.35;
  text-align: left;
}
.starter-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 9px;
  background: var(--primary-glaze);
  box-shadow: var(--primary-shadow);
  color: var(--on-primary);
}
/* Catppuccin tints each starter with its own pastel instead of the primary glaze. */
:root[data-art='catppuccin'] .starter-icon {
  --tint: var(--link);
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--tint) 24%, transparent),
    color-mix(in srgb, var(--tint) 13%, transparent)
  );
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tint) 22%, transparent);
  color: var(--tint);
}
:root[data-art='catppuccin'] .starter:nth-child(2) .starter-icon {
  --tint: var(--success);
}
:root[data-art='catppuccin'] .starter:nth-child(3) .starter-icon {
  --tint: var(--warning);
}
:root[data-art='catppuccin'] .starter:nth-child(4) .starter-icon {
  --tint: var(--accent-text);
}
@media (max-width: 720px) {
  .starters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
.chat-empty > .message-note {
  position: absolute;
  right: 24px;
  bottom: 0;
  left: 24px;
  margin: 0;
  font-size: 12px;
  letter-spacing: normal;
  color: var(--text-tertiary);
}
.chat-empty > .text-error {
  padding: 0 24px;
  color: var(--error);
  font-size: 12px;
  letter-spacing: normal;
}
.project-switcher {
  width: fit-content;
  max-width: 100%;
  margin: 8px auto 0;
  text-align: left;
}
.project-switcher .select-trigger {
  width: auto;
  max-width: min(480px, calc(100vw - 48px));
  min-height: 44px;
  padding: 0 10px;
  border: 0;
  background: transparent;
  color: var(--text-secondary);
  font-size: 20px;
  letter-spacing: -0.02em;
}
.project-switcher .select-menu {
  right: auto;
  left: 50%;
  width: min(360px, calc(100vw - 48px));
  transform: translateX(-50%);
}
.project-switcher .select-menu li {
  height: auto;
  min-height: 44px;
  padding: 8px;
