.pair-screen {
  display: grid;
  place-items: center;
  min-height: 100dvh;
  padding: 24px;
  background: var(--surface);
  color: var(--text);
}
.pair-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  width: min(100%, 360px);
  text-align: center;
}
.pair-icon {
  width: 72px;
  height: 72px;
}
.pair-card h1 {
  font-size: 20px;
  font-weight: 600;
}
.pair-card p {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.5;
}
.pair-card input {
  width: 100%;
  height: 44px;
  padding: 0 12px;
  border: 1px solid var(--border-heavy);
  border-radius: 10px;
  background: var(--control);
  color: var(--text);
  font-family: var(--font-mono);
  /* 16px keeps iOS from zooming into the field. */
  font-size: 16px;
  letter-spacing: 0.08em;
  text-align: center;
  text-transform: uppercase;
}
.pair-card .button {
  width: 100%;
}
.pair-card .field-error {
  color: var(--error);
  text-align: center;
}

sources.features/workbench/workbench-rail.css:
.wb-rail {
  display: flex;
  flex: none;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  width: 44px;
  padding: 0 4px 6px;
  border-left: 1px solid var(--border);
  background: var(--surface);
}
.wb-rail > button {
  position: relative;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  flex: none;
  border-radius: 10px;
  color: var(--text-tertiary);
}
.wb-rail-badge {
  position: absolute;
  top: 0;
  right: -1px;
  display: grid;
  place-items: center;
  min-width: 13px;
  height: 13px;
  padding-inline: 2px;
  border-radius: 7px;
  background: var(--accent);
  color: var(--on-accent);
  outline: 1px solid var(--surface);
  font-size: 9px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  pointer-events: none;
}
.wb-rail-badge[data-error='true'] {
  background: var(--surface);
  color: var(--error);
}
/* The open view is a raised ceramic tile. */
.wb-rail > button[aria-pressed='true'] {
  color: var(--text);
  background: var(--glaze);
  box-shadow: var(--glaze-shadow);
}
@media (hover: hover) {
  .wb-rail > button:hover {
    color: var(--text);
    background: var(--hover);
  }
}
@media (pointer: coarse) {
  .wb-rail {
    width: 52px;
  }
  .wb-rail > button {
    width: 44px;
    height: 44px;
  }
}
.wb-rail-header {
  display: grid;
  place-items: center;
  flex: none;
  height: var(--toolbar-height);
  width: calc(100% + 8px);
  border-bottom: 1px solid var(--border);
}
/* Phones keep the chat full width; the header's panel toggle opens the workspace, and the
   rail returns beside an open panel to switch views. */
@media (max-width: 720px) {
  .workspace-body:not(:has(.workbench:not([hidden]))) > .wb-rail {
    display: none;
  }
}

sources.features/workbench/image-viewer.css:
.wb-image-viewer {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.wb-image-toolbar {
  flex-wrap: wrap;
}
.wb-image-meta {
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.wb-image-scale {
  width: 56px;
  font-variant-numeric: tabular-nums;
}
.wb-image-toolbar .wb-actions {
  gap: 2px;
}
.wb-image-toolbar [aria-pressed='true'],
.wb-image-footer [aria-pressed='true'] {
  background: var(--selected);
}
.wb-image-download {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 5px;
}
.wb-image-viewport {
  flex: 1;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  background: var(--surface-under);
}
.wb-image-viewport:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
.wb-image-viewport[data-pan='true'] {
  cursor: grab;
}
.wb-image-viewport[data-dragging='true'] {
  cursor: grabbing;
  user-select: none;
}
.wb-image-viewport[data-annotating='true'] {
  cursor: crosshair;
}
.wb-image-canvas {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 100%;
  min-height: 100%;
  padding: 16px;
}
.wb-image-canvas img {
  display: block;
  flex: none;
  max-width: none;
  user-select: none;
  background: repeating-conic-gradient(var(--secondary) 0% 25%, var(--surface) 0% 50%) 0 0 / 16px
    16px;
  box-shadow: 0 0 0 1px var(--border);
}
.wb-image-footer {
  border-top: 1px solid var(--border);
  border-bottom: 0;
}
@media (hover: hover) {
  .wb-image-download:hover {
    background: var(--hover);
  }
}
@media (pointer: coarse) {
  .wb-image-toolbar button,
  .wb-image-download,
  .wb-image-footer button {
    min-width: 44px;
    min-height: 44px;
  }
}

sources.features/workbench/open-in-app.css:
.open-app {
  anchor-scope: --open-app;
  display: inline-flex;
  flex: none;
  align-items: stretch;
  height: 36px;
  anchor-name: --open-app;
  -webkit-app-region: no-drag;
}
.open-app-trigger {
  display: grid;
  place-items: center;
  color: var(--text-secondary);
  position: relative;
  width: 36px;
  border-radius: 6px;
}
.open-app-trigger[aria-expanded='true'] {
  background: var(--selected);
}
.open-app img {
  flex: none;
  object-fit: contain;
}
.open-app-menu {
  position: fixed;
  position-anchor: --open-app;
  inset: auto;
  top: calc(anchor(bottom) + 6px);
  right: anchor(right);
  margin: 0;
  width: 224px;
  max-width: calc(100vw - 24px);
  max-height: min(480px, calc(100dvh - 64px));
  overflow-y: auto;
  padding: 5px;
  border: 1px solid var(--border-heavy);
  border-radius: 12px;
  background: var(--elevated);
  color: var(--text);
  box-shadow: var(--shadow);
  font-size: 13px;
  -webkit-app-region: no-drag;
}
.open-app-menu button {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 32px;
  padding: 6px 9px;
  border-radius: 6px;
  text-align: left;
}
.open-app-check {
  margin-left: auto;
  color: var(--accent-text);
}
.open-app-menu [role='separator'] {
  height: 1px;
  margin: 5px -5px;
  background: var(--border);
}
.open-app-menu button:focus-visible {
  background: var(--selected);
}
.open-app-note {
  padding: 8px 9px;
  color: var(--text-secondary);
  font-size: 12px;
  overflow-wrap: anywhere;
}
.open-app-note.text-error {
  color: var(--error);
}
.open-app-status {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
@media (hover: hover) {
  .open-app button:hover:not(:disabled) {
    background: var(--hover);
  }
}
@media (pointer: coarse) {
  .open-app {
    height: 44px;
  }
  .open-app-trigger {
    width: 44px;
  }
  .open-app-menu button {
    min-height: 44px;
  }
}

sources.features/workbench/file-reveal.css:
.wb-file-reveal {
  position: relative;
  flex: none;
  height: 32px;
}
.wb-file-reveal .open-app-trigger {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
}
@media (pointer: coarse) {
  .wb-file-reveal {
    height: 44px;
  }
}

sources.features/workbench/markdown-file.css:
.wb-markdown-file {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.wb-markdown-modes {
  display: flex;
  gap: 2px;
  padding: 2px;
  border-radius: 7px;
  background: var(--surface-under);
}
.wb-markdown-modes [aria-pressed='true'] {
  background: var(--control);
  color: var(--text);
}
.wb-markdown-scroll {
  flex: 1;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
}
.wb-markdown-scroll:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
.wb-markdown-prose {
  max-width: 820px;
  margin-inline: auto;
  padding: 32px clamp(20px, 5cqi, 48px) 64px;
  font-size: 14px;
  line-height: 1.75;
  overflow-wrap: anywhere;
  color: var(--text-secondary);
}
.wb-markdown-prose > :first-child {
  margin-top: 0;
}
.wb-markdown-prose :is(h1, h2, h3, h4, h5, h6) {
  color: var(--text);
  scroll-margin-top: 24px;
  letter-spacing: -0.02em;
}
.wb-markdown-prose h1 {
  font-size: 26px;
  line-height: 1.3;
  margin-bottom: 24px;
}
.wb-markdown-prose h2 {
  font-size: 20px;
  margin-top: 32px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border);
}
.wb-markdown-prose h3 {
  font-size: 16px;
  margin-top: 24px;
}
.wb-markdown-prose strong,
.wb-markdown-prose th {
  color: var(--text);
  font-weight: 600;
}
.wb-markdown-prose th {
  text-align: left;
}
.wb-markdown-prose td,
.wb-markdown-prose th {
  padding: 9px 14px;
}
.wb-markdown-prose pre {
  line-height: 1.6;
  overflow-wrap: normal;
}
.wb-markdown-prose code {
  font-size: 0.9em;
}
.wb-markdown-prose hr {
  margin-block: 28px;
  border: 0;
  border-top: 1px solid var(--border);
}
.wb-markdown-prose input[type='checkbox'] {
  margin-right: 6px;
  accent-color: var(--accent);
}
.wb-markdown-prose .contains-task-list {
  list-style: none;
  padding-left: 4px;
}
.wb-markdown-prose .markdown-image {
  display: block;
  margin-block: 20px;
}
.wb-markdown-prose .markdown-image img {
  max-height: none;
}
@media (pointer: coarse) {
  .wb-markdown-modes button {
    min-height: 44px;
    min-width: 44px;
  }
}

sources.features/workbench/docx-viewer.css:
.wb-docx-viewer {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.wb-docx-viewer > .wb-subtoolbar {
  display: flex;
  align-items: center;
  min-height: 32px;
  padding: 6px 16px;
  border-bottom: 1px solid var(--border);
  color: var(--text-secondary);
  font-size: 12px;
}
.wb-docx-scroll {
  flex: 1;
  overflow: auto;
  padding: clamp(12px, 3vw, 32px);
  background: var(--surface-under);
}
.wb-docx-scroll:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
.wb-docx-page {
  max-width: 800px;
  margin: 0 auto;
  padding: clamp(20px, 5vw, 64px);
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--card-shadow);
  font: 15px/1.65 var(--font-sans);
  overflow-wrap: anywhere;
}
.wb-docx-page p,
.wb-docx-page ul,
.wb-docx-page ol {
  margin: 0 0 1em;
}
.wb-docx-page h1,
.wb-docx-page h2,
.wb-docx-page h3,
.wb-docx-page h4,
.wb-docx-page h5,
.wb-docx-page h6 {
  margin: 1.25em 0 0.5em;
  line-height: 1.3;
  font-weight: 600;
}
.wb-docx-page h1 {
  font-size: 1.6em;
}
.wb-docx-page h2 {
  font-size: 1.35em;
}
.wb-docx-page h3 {
  font-size: 1.15em;
}
.wb-docx-page > :first-child {
  margin-top: 0;
}
.wb-docx-page td > :last-child,
.wb-docx-page th > :last-child {
  margin-bottom: 0;
}
.wb-docx-page ul,
.wb-docx-page ol {
  padding-left: 1.5em;
}
.wb-docx-page ul {
  list-style: disc;
}
.wb-docx-page ol {
  list-style: decimal;
}
.wb-docx-page img {
  max-width: 100%;
  height: auto;
}
.wb-docx-page table {
  border-collapse: collapse;
  width: 100%;
  margin: 1em 0;
}
.wb-docx-page td,
.wb-docx-page th {
  border: 1px solid var(--border-heavy);
  padding: 8px;
  vertical-align: top;
}
.wb-docx-page pre {
  white-space: pre-wrap;
}
.docx-preview-dialog {
  width: min(1000px, calc(100vw - 32px));
  height: min(900px, calc(100dvh - 32px));
  max-width: none;
  max-height: none;
  margin: auto;
  padding: 0;
  border: 1px solid var(--border-heavy);
  border-radius: 12px;
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--shadow);
}
.docx-preview-dialog[open] {
  display: flex;
  flex-direction: column;
}
.docx-preview-dialog::backdrop {
  background: var(--scrim);
}
.docx-preview-dialog header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border);
}
.docx-preview-dialog header > span {
  flex: 1;
}

sources.features/workbench/video-viewer.css:
.wb-video-viewer {
  display: flex;
