sources.features/workbench/workbench.css:
.workbench {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: none;
  min-width: 340px;
  max-width: calc(100% - 320px);
  min-height: 0;
  border-left: 1px solid var(--border);
  background: var(--surface);
  font-size: 12px;
  isolation: isolate;
  container-type: inline-size;
}
.workbench[hidden],
.workbench [hidden] {
  display: none !important;
}
.workspace-body[data-workbench-expanded='true'] > .chat-column {
  visibility: hidden;
}
.workbench[data-expanded='true'] {
  position: absolute;
  inset: 0 44px 0 0;
  width: auto !important;
  min-width: 0;
  max-width: none;
  border-left: 0;
  z-index: 5;
}
@media (pointer: coarse) {
  .workbench[data-expanded='true'] {
    right: 52px;
  }
}
@media (min-width: 721px) {
  :root[data-platform='darwin']:not([data-fullscreen='true'])
    .app-shell[data-sidebar-collapsed='true']
    .workbench[data-expanded='true']
    .wb-header {
    padding-left: 88px;
  }
}
.wb-content,
.wb-surface,
.wb-diff-preview,
.wb-file-editor,
.wb-editor-workspace,
.wb-document-content,
.wb-document {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.wb-header,
.wb-subtoolbar,
.wb-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.wb-header {
  justify-content: space-between;
  height: var(--toolbar-height);
  flex: none;
  padding: 0 8px 0 0;
  border-bottom: 1px solid var(--border);
}
.wb-header-content {
  display: flex;
  flex: 1;
  min-width: 0;
  height: 100%;
  overflow: hidden;
}
.wb-header-content:empty {
  display: none;
}
.wb-header-content:not(:empty) + .wb-heading {
  display: none;
}
.wb-heading {
  flex: 1;
  min-width: 0;
  padding-left: 12px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
:root[data-platform] .wb-header {
  -webkit-app-region: drag;
}
:root[data-platform] .wb-header button,
:root[data-platform] .wb-document-tabs {
  -webkit-app-region: no-drag;
}
.wb-subtoolbar {
  justify-content: space-between;
  padding: 5px 10px;
  flex-shrink: 0;
  border-bottom: 1px solid var(--border);
}
.wb-actions {
  margin-left: auto;
  flex-shrink: 0;
}
.wb-note {
  color: var(--text-tertiary);
  font-size: 12px;
}
.workbench input,
.workbench select {
  height: 28px;
  padding: 0 9px;
  min-width: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--border-heavy);
  color: var(--text);
}
/* Pickers are glazed chips; text fields are quiet rings. */
.workbench select {
  border: 1px solid var(--chip-border);
  background: var(--chip);
  box-shadow: var(--chip-shadow);
  font-weight: 500;
}
.workbench select {
  max-width: 100%;
}
.wb-added {
  color: var(--success);
}
.wb-removed {
  color: var(--error);
}
.wb-empty {
  margin: auto;
  padding: 24px;
  text-align: center;
  color: var(--text-secondary);
}
.wb-empty > svg {
  margin: 0 auto 16px;
  color: var(--text-tertiary);
}
.wb-empty h3 {
  margin-bottom: 8px;
  color: var(--text);
  font-size: 14px;
  font-weight: 500;
}
.wb-empty p + p {
  margin-top: 8px;
}
.wb-empty .button {
  margin-top: 12px;
}
.wb-notice {
  flex-shrink: 0;
  font-size: 11px;
  padding: 8px 12px;
  color: var(--text-tertiary);
  overflow-wrap: anywhere;
}
.wb-notice.text-error {
  color: var(--error);
}
.wb-resize,
.wb-tree-resize {
  position: absolute;
  inset: 0 auto 0 -4px;
  width: 8px;
  cursor: col-resize;
  z-index: 4;
  touch-action: none;
}
.wb-resize:focus-visible,
.wb-tree-resize:focus-visible {
  background: var(--accent-soft);
}
/* The seam grip: half paper, half ink, where the conversation meets the review panel. */
.wb-resize::before {
  content: '';
  position: absolute;
  top: calc(50% - 28px);
  left: -1px;
  width: 10px;
  height: 56px;
  border-radius: 5px;
  background:
    linear-gradient(90deg, transparent 50%, var(--control) 50%, var(--surface-under) 100%),
    var(--glaze);
  box-shadow: var(--glaze-shadow);
}
.workbench[data-resizing]::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 3;
  cursor: col-resize;
}
.wb-editor-layout {
  display: flex;
  flex: 1;
  min-height: 0;
  min-width: 0;
}
.wb-document-tabs {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 4px;
  min-width: 0;
  height: 100%;
  padding-left: 10px;
  overflow-x: auto;
  scrollbar-width: none;
}
/* Open files are pills; the active one is glazed. */
.wb-document-tab {
  display: flex;
  flex: none;
  align-items: center;
  gap: 2px;
  height: 28px;
  max-width: 240px;
  padding-right: 4px;
  border-radius: 8px;
  color: var(--text-tertiary);
  font-size: 12.5px;
}
.wb-document-tab[data-active='true'] {
  background: var(--glaze);
  box-shadow: var(--glaze-shadow);
  color: var(--text);
}
.wb-document-tab > button {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 4px 6px 4px 10px;
  white-space: nowrap;
  min-width: 0;
}
.wb-document-tab > [role='tab'] {
  flex: 1;
}
.wb-document-tab > [role='tab'] > span:first-of-type {
  overflow: hidden;
  text-overflow: ellipsis;
}
.wb-document-tab [data-preview='true'] > span:first-of-type {
  font-style: italic;
}
.wb-document-tab > button:last-child {
  padding: 3px;
  border-radius: 5px;
  color: var(--text-tertiary);
}
.wb-document-tab svg {
  flex: none;
}
.wb-tab-kind {
  font-size: 10px;
  color: var(--text-tertiary);
}
.wb-tabs-placeholder {
  align-self: center;
  padding: 0 12px;
  color: var(--text-tertiary);
}
.wb-breadcrumbs {
  display: flex;
  align-items: center;
  min-height: 40px;
  padding: 0 8px 0 12px;
  gap: 8px;
  border-bottom: 1px solid var(--border);
}
.wb-breadcrumbs nav {
  display: flex;
  flex: 1;
  min-width: 0;
  overflow-x: auto;
  white-space: nowrap;
  scrollbar-width: none;
  color: var(--text-secondary);
}
.wb-breadcrumb-separator {
  padding: 0 7px;
  color: var(--text-tertiary);
}
.wb-breadcrumbs .button {
  flex: none;
  font-size: 11px;
}
/* One document toolbar; totals live in the tree footer and individual diff headers. */
.wb-breadcrumbs[data-view='changes'] .segmented {
  flex: none;
}
.wb-toolbar-slot {
  display: flex;
  flex: none;
  margin-left: auto;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  min-width: 0;
}
.wb-toolbar-slot:empty {
  visibility: hidden;
}
.wb-toolbar-slot .wb-actions {
  margin-left: 0;
  gap: 4px;
}
.wb-toolbar-slot .segmented[data-icon-only] button {
  width: 28px;
  padding: 0;
  justify-content: center;
}
.wb-toolbar-slot .wb-note {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  max-width: 100px;
}
.wb-explorer {
  display: flex;
  flex-direction: column;
  flex: none;
  min-height: 0;
  position: relative;
  border-left: 1px solid var(--border);
  background: var(--surface-under);
}
.wb-explorer-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 36px;
  padding: 0 8px 0 12px;
  border-bottom: 1px solid var(--border);
  color: var(--text-secondary);
}
.wb-explorer-heading > span {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.wb-explorer-heading .segmented {
  flex: 1;
  min-width: 0;
}
.wb-explorer-heading .segmented button {
  flex: 1;
  justify-content: center;
  height: 24px;
  padding: 0 8px;
}
.wb-tree-pane {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
.wb-tree-tools {
  display: flex;
  padding: 8px;
  gap: 4px;
}
.wb-tree-tools input {
  width: 100%;
  font-size: 12px;
}
.wb-pierre-tree {
  display: block;
  flex: 1;
  overflow: hidden;
}
/* Only the status letter carries color; on the calico's ink, file icons are monochrome too. */
:root[data-art='calico'] .wb-pierre-tree {
  --tree-icon-filter: grayscale(1);
}
.wb-explorer-footer {
  display: flex;
  gap: 8px;
  padding: 8px 10px;
  color: var(--text-tertiary);
  border-top: 1px solid var(--border);
  font-family: var(--font-mono);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.wb-explorer-footer > span:first-child {
  margin-right: auto;
}
.wb-pierre-diff {
  flex: 1;
  min-height: 0;
  overflow: auto;
}
.wb-editor {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
.wb-editor .cm-editor {
  height: 100%;
  font-size: 12px;
}
.wb-editor .cm-scroller {
  font-family: var(--font-mono);
  overflow: auto;
  line-height: 1.7;
}
.wb-editor .cm-content {
  caret-color: var(--text);
}
.wb-editor .cm-gutters {
  background: var(--surface);
  color: var(--text-tertiary);
  border-right: 1px solid var(--border);
}
.wb-editor .cm-activeLine,
.wb-editor .cm-activeLineGutter {
  background: var(--secondary);
}
.wb-editor .cm-selectionBackground,
.wb-editor .cm-editor.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground {
  background: var(--accent-soft);
}
.wb-editor .cm-comment-widget {
  position: sticky;
  left: var(--cm-comment-left, 0px);
  width: var(--cm-comment-width, 100%);
  max-width: 100%;
  box-sizing: border-box;
  background: var(--surface);
  user-select: none;
}
.wb-editor .cm-comment-widget textarea {
  user-select: text;
}
.wb-editor .comment-actions {
  flex-wrap: wrap;
}
.wb-editor .comment-actions > span {
  flex: 1 1 120px;
}
.wb-editor .cm-cursor {
  border-left-color: var(--text);
}
.wb-editor .cm-editor.cm-focused {
  outline: none;
}
.wb-editor:focus-within {
  box-shadow: inset 0 0 0 1px var(--border-heavy);
}
@media (hover: hover) {
  .wb-document-tab > button:hover {
    background: var(--hover);
  }
  .wb-resize:hover,
  .wb-tree-resize:hover {
    background: var(--accent-soft);
  }
}
@container (max-width: 560px) {
  .wb-editor-layout {
    position: relative;
  }
  .wb-explorer {
    position: absolute;
    right: 0;
    top: 40px;
    bottom: 0;
    width: min(250px, 75%) !important;
    background: var(--surface);
    z-index: 2;
    box-shadow: var(--shadow);
  }
  .wb-tree-resize {
    display: none;
  }
}
@container (max-width: 400px) {
  .wb-breadcrumbs {
    gap: 4px;
    padding-inline: 6px;
  }
  .wb-toolbar-slot .wb-note {
    display: none;
  }
}
@media (pointer: coarse) {
  .wb-breadcrumbs {
    min-height: 44px;
    flex-wrap: wrap;
  }
  .wb-breadcrumbs .button-icon,
  .wb-toolbar-slot .segmented[data-icon-only] button {
    min-width: 44px;
    min-height: 44px;
  }
}
@media (max-width: 1100px) {
  .workspace-body:has(.workbench:not([hidden])) > .chat-column {
    visibility: hidden;
  }
  .workbench {
    position: absolute;
    inset: 0 44px 0 auto;
    width: calc(100% - 44px) !important;
    max-width: calc(100% - 44px);
    z-index: 5;
  }
  .wb-resize {
    display: none;
  }
}
@media (max-width: 720px) {
  .workbench {
    min-width: 0;
  }
  .workbench input,
  .workbench select {
    font-size: 16px;
  }
  .workbench .button {
    min-height: 44px;
  }
  .wb-subtoolbar > .wb-note {
    max-width: 110px;
  }
  .wb-explorer {
    top: 44px;
  }
}
@media (max-width: 1100px) and (pointer: coarse) {
  .workbench {
    right: 52px;
    width: calc(100% - 52px) !important;
    max-width: calc(100% - 52px);
  }
}

sources.features/subagents/subagent-tray.css:
.subagent-tray-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
  min-height: 30px;
  padding: 0 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  text-align: left;
}
.subagent-tray-list {
  margin: 0;
  padding: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  list-style: none;
}
.subagent-tray-row > .session-activity,
.subagent-tray-attention {
  margin: 0 2px;
}
.subagent-tray-attention {
  display: grid;
  flex: none;
  place-items: center;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  font-size: 9px;
  font-weight: 700;
  line-height: 1;
}
.subagent-tray-attention[data-kind='permission'] {
  background: var(--warning);
  color: var(--surface);
}
.subagent-tray-attention[data-kind='question'] {
  background: var(--accent);
  color: var(--on-accent);
}
.subagent-tray-agent {
  flex: none;
  color: var(--text);
  font-weight: 500;
}
.subagent-tray-title {
  flex: 1;
}
.subagent-tray-meta {
  flex: none;
  color: var(--text-tertiary);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.subagent-tray-meta[data-status='permission'] {
  color: var(--warning);
}
.subagent-tray-meta[data-status='question'] {
  color: var(--accent-text);
}
.subagent-tray-meta[data-status='error'] {
  color: var(--error);
}
.subagent-tray-open {
  color: var(--text-tertiary);
  opacity: 0;
}
.subagent-tray-row:focus-visible {
  background: var(--selected);
  color: var(--text);
}
.subagent-tray-row:focus-visible > .subagent-tray-open {
  opacity: 1;
}
@media (hover: hover) {
  .subagent-tray-row:hover {
    background: var(--hover);
    color: var(--text);
  }
  .subagent-tray-row:hover > .subagent-tray-open {
    opacity: 1;
  }
}
@media (pointer: coarse) {
  .subagent-tray-row {
    min-height: 44px;
  }
  .subagent-tray-open {
    opacity: 1;
  }
}
/* Narrow chat columns drop the agent name to keep each task title and status legible. */
@container (max-width: 360px) {
  .subagent-tray-agent {
    display: none;
  }
}

sources.features/subagents/subagents.css:
.subagents-panel,
.subagent-reader,
.subagents-list-pane {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.subagents-panel,
.subagent-reader {
  flex: 1;
  overflow: hidden;
}
.subagents-list-pane {
  flex: 1;
  overflow: hidden;
}
.subagents-list-pane .wb-empty {
  padding: 12px;
}
.subagents-list-pane .wb-empty > svg {
  margin-bottom: 8px;
}
.subagents-panel h2,
.subagent-session-header h3 {
  font-size: 14px;
  font-weight: 500;
}
.subagents-panel .wb-note {
  font-variant-numeric: tabular-nums;
}
.subagents-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.subagent-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  width: 100%;
  min-width: 0;
  padding: 10px 12px;
  text-align: left;
  color: var(--text-secondary);
}
.subagent-avatar {
  display: grid;
  place-items: center;
  flex: none;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-soft);
  color: var(--accent-text);
}
.subagent-row > svg {
  align-self: center;
  color: var(--text-tertiary);
}
.subagent-row-info {
  flex: 1;
  min-width: 0;
  font-size: var(--chat-font-size);
}
.subagent-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-tertiary);
  font-size: 12px;
}
.subagent-meta > span:last-child {
  flex: none;
}
.subagents-filter {
  display: flex;
  align-items: center;
  flex: none;
}
.subagent-meta [data-status='failed'] {
  color: var(--error);
}
.subagents-more {
  display: flex;
  justify-content: center;
  flex: none;
  padding: 4px;
}
.subagent-session-header {
  display: flex;
  flex: none;
  align-items: center;
  gap: 12px;
  min-width: 0;
  padding: 12px;
  border-bottom: 1px solid var(--border);
}
.subagent-session-header .button {
  flex: none;
}
.subagent-session-details {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  gap: 4px;
}
.subagent-session-model {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  color: var(--text-tertiary);
  font-size: 12px;
}
.subagent-session-model .provider-logo,
.subagent-session-model .provider-logo-fallback {
  width: 14px;
  height: 14px;
}
.subagent-session-header .session-activity {
  position: static;
  flex: none;
}
.subagent-reader {
  font-size: var(--chat-font-size);
}
.subagent-reader .timeline-row,
.subagent-reader .timeline-footer {
  padding-inline: 16px;
}
.subagent-reader .user-message-bubble {
  max-width: 100%;
}
@media (hover: hover) {
  .subagent-row:hover {
    background: var(--hover);
  }
}
@media (pointer: coarse) {
  .subagent-row,
  .subagents-more .button {
    min-height: 48px;
  }
}
@media (max-width: 720px) {
  .subagent-reader,
  .subagent-row-info {
    font-size: 16px;
  }
}

sources.features/chat/comments.css:
.comment-editor,
.comment-card {
  font: 13px/1.5 var(--font-sans);
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  white-space: normal;
  min-width: 0;
}
.comment-editor {
  padding: 10px;
  margin: 6px;
}
.comment-source {
  display: block;
  color: var(--text-secondary);
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.comment-editor textarea {
  display: block;
  width: 100%;
  min-height: 64px;
  max-height: 200px;
  field-sizing: content;
  resize: vertical;
  margin: 8px 0;
  padding: 4px 0;
  border: 0;
  background: transparent;
  color: var(--text);
  font: inherit;
}
.comment-editor textarea:focus-visible {
  outline: none;
}
.comment-editor blockquote {
  margin: 8px 0;
  padding-left: 10px;
  border-left: 2px solid var(--border);
  color: var(--text-secondary);
  max-height: 90px;
  overflow: auto;
  white-space: pre-wrap;
}
.comment-actions {
  display: flex;
  gap: 6px;
  align-items: center;
}
.comment-actions > span {
  margin-right: auto;
  color: var(--text-tertiary);
  font-size: 10px;
}
.comment-card {
  display: flex;
  align-items: center;
  margin: 6px;
}
.comment-card-body {
  flex: 1;
  min-width: 0;
  text-align: left;
  border: 0;
  background: none;
  color: inherit;
  padding: 8px 10px;
  cursor: pointer;
  font: inherit;
}
.comment-summary {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}
.composer-context {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding: 0 0 8px;
  anchor-name: --composer-context;
}
.composer-context-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0 10px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface);
  color: var(--text-secondary);
  font: 12px/1 var(--font-sans);
}
.composer-context-count {
  color: var(--accent-text);
  font-variant-numeric: tabular-nums;
}
.composer-context-chip[aria-expanded='true'] {
  background: var(--selected);
  border-color: var(--border-heavy);
}
.composer-context-preview {
  position: fixed;
  position-anchor: --composer-context;
  inset: auto;
  left: anchor(left);
  bottom: calc(anchor(top) + 6px);
  position-try-fallbacks: flip-inline, flip-block;
  width: 400px;
  max-width: calc(100vw - 32px);
  max-height: min(420px, calc(100dvh - 240px));
  margin: 0;
  padding: 0;
  overflow: auto;
  border: 1px solid var(--border-heavy);
  border-radius: 12px;
  background: var(--elevated);
  color: var(--text);
  box-shadow: var(--shadow);
  font: 13px/1.5 var(--font-sans);
}
.context-entry + .context-entry {
  border-top: 1px solid var(--border);
}
.context-entry header {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 8px 6px 12px;
  background: var(--secondary);
}
.context-entry-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-secondary);
  font-size: 11px;
}
.context-entry-action {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 5px;
  color: var(--text-secondary);
}
.context-entry-content {
  padding: 10px 12px;
}
.context-entry-content blockquote {
  margin: 0;
  padding-left: 10px;
  max-height: 120px;
  overflow: auto;
  border-left: 2px solid var(--border-heavy);
  color: var(--text-secondary);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.context-entry-content blockquote[data-code='true'] {
  font-family: var(--font-mono);
  font-size: 12px;
}
.context-entry-content p {
  margin: 8px 0 0;
  max-height: 120px;
  overflow: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.context-entry-content textarea {
  display: block;
  width: 100%;
  field-sizing: content;
  resize: none;
  min-height: 54px;
  max-height: 160px;
  margin-top: 8px;
  padding: 6px 8px;
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--border-heavy);
  border-radius: 6px;
  font: inherit;
}
@media (hover: hover) {
  .composer-context-chip:hover,
  .context-entry-action:hover {
    background: var(--hover);
    color: var(--text);
  }
}
@media (pointer: coarse) {
  .composer-context-chip {
    min-height: 44px;
  }
  .context-entry-action {
    width: 44px;
    height: 44px;
  }
  .context-entry-content textarea {
    font-size: 16px;
  }
}
.response-selection {
  position: fixed;
  z-index: 30;
  max-width: calc(100vw - 24px);
  max-height: calc(100dvh - 24px);
  overflow: auto;
}
.response-selection-actions {
  display: flex;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  box-shadow: var(--shadow);
}
.response-selection .comment-editor {
  width: 340px;
  max-width: calc(100vw - 24px);
  margin: 0;
  box-shadow: var(--shadow);
}
.cm-comment-widget {
  padding: 1px 8px;
}
.cm-comment-gutter button {
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text-tertiary);
  font: inherit;
  cursor: pointer;
}
@media (hover: hover) {
  .cm-comment-gutter button {
    opacity: 0;
  }
  .cm-comment-gutter button:hover {
    opacity: 1;
  }
  .cm-comment-gutter button:hover {
    background: var(--accent-soft);
    color: var(--accent-text);
  }
  .comment-card-body:hover {
    background: var(--hover);
    border-radius: 10px;
  }
}
::highlight(response-comment),
::highlight(preview-comment) {
  background: var(--accent-soft);
  color: var(--text);
}
::highlight(reviewed-response) {
  background: var(--accent-soft);
  text-decoration: underline;
  text-decoration-color: var(--accent);
}
@media (pointer: coarse) {
  .comment-editor textarea {
    font-size: 16px;
  }
  .comment-card-body {
    min-height: 44px;
  }
}
.message-annotations {
  anchor-scope: --message-annotations;
}
/* "From side chat" above a message a side chat sent. */
.message-source {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-bottom: -2px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-tertiary);
  font: inherit;
  font-size: 12px;
}
button.message-source {
  cursor: pointer;
}
button.message-source:hover {
  color: var(--text-secondary);
}
button.message-source:focus-visible {
  outline: 2px solid var(--border-heavy);
  outline-offset: 2px;
  border-radius: 4px;
}
.message-annotations-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--user-message);
  color: var(--text);
  font: inherit;
  font-size: var(--chat-font-size);
  anchor-name: --message-annotations;
  cursor: pointer;
}
.message-annotations-chip > svg {
  color: var(--text-secondary);
}
.message-annotations-chip:focus-visible {
  outline: 2px solid var(--border-heavy);
  outline-offset: 2px;
}
.message-annotations-preview {
  position: fixed;
  position-anchor: --message-annotations;
  inset: auto;
  top: calc(anchor(bottom) + 6px);
  right: anchor(right);
  position-try-fallbacks: flip-block;
  width: 400px;
  max-width: calc(100vw - 32px);
  max-height: min(320px, calc(100dvh - 32px));
  margin: 0;
  padding: 0;
  overflow: auto;
  border: 1px solid var(--border-heavy);
  border-radius: 12px;
  background: var(--elevated);
  color: var(--text);
  box-shadow: var(--shadow);
  font: 13px/1.5 var(--font-sans);
}
.message-annotations-preview ol {
  margin: 0;
  padding: 0;
  list-style: none;
}
.message-annotations-preview li {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 12px;
}
.message-annotations-preview li + li {
  border-top: 1px solid var(--border);
}
.message-annotation-number {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 500;
}
.message-annotation-source {
  overflow: hidden;
  color: var(--text-tertiary);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.message-annotations-preview small {
  margin-top: 4px;
  color: var(--text-tertiary);
  font-size: 11px;
  font-weight: 500;
}
.message-annotations-preview blockquote,
.message-annotations-preview p {
  margin: 0;
  max-height: 120px;
  overflow: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.message-annotations-preview blockquote {
  padding-left: 10px;
  border-left: 2px solid var(--border-heavy);
  color: var(--text-secondary);
}
.message-annotations-preview blockquote[data-code='true'] {
  font-family: var(--font-mono);
  font-size: 12px;
}
@media (hover: hover) {
  .message-annotations-chip:hover {
    background: var(--secondary-hover);
  }
