sources.features/chat/context-indicator.css:
.context-indicator {
  flex-shrink: 0;
  anchor-scope: --context-indicator;
}
.context-indicator-trigger {
  anchor-name: --context-indicator;
}
.composer-controls .context-indicator-trigger.button {
  width: 32px;
  height: 32px;
}
.context-indicator-trigger[aria-expanded='true'] {
  background: var(--hover);
}
.context-indicator svg {
  fill: none;
  stroke-width: 2.5;
}
.context-ring-track {
  stroke: var(--border-heavy);
}
.context-ring-value {
  stroke: var(--text-secondary);
}
.context-indicator svg[data-level='high'] .context-ring-value {
  stroke: var(--warning);
}
.context-indicator svg[data-level='critical'] .context-ring-value {
  stroke: var(--error);
}
.context-popover {
  position: fixed;
  position-anchor: --context-indicator;
  inset: auto;
  bottom: calc(anchor(top) + 8px);
  right: anchor(right);
  position-try-fallbacks: flip-inline, flip-block;
  width: min(280px, calc(100vw - 24px));
  margin: 0;
  padding: 14px;
  border: 1px solid var(--border-heavy);
  border-radius: 12px;
  background: var(--elevated);
  box-shadow: var(--shadow);
  color: var(--text-secondary);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.context-popover-heading {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: var(--text);
}
.context-popover p + p {
  margin-top: 4px;
  color: var(--text-tertiary);
}
.context-popover progress {
  display: block;
  appearance: none;
  width: 100%;
  height: 4px;
  margin-block: 12px;
  overflow: hidden;
  border: 0;
  border-radius: 4px;
  background: var(--secondary-hover);
  color: var(--text-secondary);
}
.context-popover progress::-webkit-progress-bar {
  background: var(--secondary-hover);
}
.context-popover progress::-webkit-progress-value {
  border-radius: 4px;
  background: var(--text-secondary);
}
.context-popover progress::-moz-progress-bar {
  border-radius: 4px;
  background: var(--text-secondary);
}
@media (pointer: coarse) {
  .composer-controls .context-indicator-trigger.button {
    width: 44px;
    height: 44px;
  }
}

sources.features/chat/markdown-image.css:
.markdown-image {
  display: block;
  margin-block: 12px;
  max-width: 100%;
}
.markdown-image .image-attachment-trigger {
  max-width: 100%;
  overflow: hidden;
  border-radius: 8px;
}
.markdown-image img {
  width: auto;
  height: auto;
  max-width: 100%;
  max-height: 560px;
  object-fit: contain;
}
.markdown-image-error {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  color: var(--text-muted);
  font-size: 13px;
}
.markdown-image-error button {
  min-height: 44px;
  padding: 0 8px;
  border: 0;
  background: transparent;
  color: var(--text);
  font: inherit;
  text-decoration: underline;
  cursor: pointer;
}

sources.features/chat/turn-header.css:
.timeline-row[data-row-type='turn'] {
  padding-bottom: 12px;
}
/* A quiet label between a turn's work and its answer. */
.turn-work {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 24px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text-tertiary);
  font: inherit;
  font-size: 13px;
  text-align: left;
}
.turn-work-label {
  flex: none;
  font-variant-numeric: tabular-nums;
}
.turn-work-chevron {
  flex: none;
