}
.turn-work:focus-visible {
  color: var(--text);
}
@media (hover: hover) {
  .turn-work:hover {
    color: var(--text-secondary);
  }
}
@media (prefers-reduced-motion: reduce) {
  .turn-work-chevron {
    transition: none;
  }
}

sources.features/chat/response-copy.css:
.response-copy {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 28px;
  color: var(--text-tertiary);
  font-size: 12px;
  line-height: 1.5;
}
@media (hover: hover) and (pointer: fine) {
