sources.features/chat/question-dock.css:
.question-dock {
  background: var(--surface);
  border: 1px solid var(--border-heavy);
  border-radius: 18px;
  overflow: hidden;
  font-size: 13px;
}
.question-dock-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  color: var(--text-secondary);
  font-size: 12px;
}
.question-dock-header > .button {
  margin-left: auto;
  flex: none;
}
.question-topic {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-tertiary);
}
.question-queued {
  color: var(--text-tertiary);
  white-space: nowrap;
}
.question-dock-body {
  padding: 4px 10px 12px;
  max-height: min(480px, 55dvh);
  overflow-y: auto;
  overscroll-behavior: contain;
}
.question-dock-body h2 {
  margin: 0 8px 12px;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.question-dock-body fieldset {
  border: 0;
  padding: 0;
  margin: 0;
  min-width: 0;
}
.question-instruction {
  margin: -4px 8px 8px;
  color: var(--text-tertiary);
  font-size: 12px;
}
.question-choices {
  display: grid;
  gap: 3px;
}
.question-choice {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-height: 40px;
  padding: 10px;
  border-radius: 8px;
  cursor: pointer;
}
.question-choice[data-selected='true'] {
  background: var(--selected);
}
.question-choice > input {
  flex: none;
  margin: 2px 0 0;
  width: 15px;
  height: 15px;
  accent-color: var(--accent-text);
}
.question-choice-copy {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}
.question-choice-copy small {
  font-size: 12px;
  color: var(--text-tertiary);
}
.question-choice kbd {
  margin-left: auto;
  color: var(--text-tertiary);
  font: 11px/20px var(--font-sans);
}
.question-choice:has(:focus-visible) {
  background: var(--selected);
}
.question-choice input:focus-visible {
  outline: none;
}
.question-input {
  display: block;
  width: calc(100% - 16px);
  margin: 6px 8px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--secondary);
  color: var(--text);
  font: inherit;
  field-sizing: content;
  resize: none;
  min-height: 40px;
  max-height: 140px;
}
.question-input:focus-visible {
  outline: none;
  border-color: var(--border-heavy);
}
.question-input::placeholder {
  color: var(--text-tertiary);
}
.question-external,
.question-error {
  margin: 8px;
}
.question-external a {
  color: var(--accent-text);
}
.question-collapsed {
  padding: 0 18px 12px;
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.question-dock-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 14px;
  border-top: 1px solid var(--border);
}
.question-dock-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.question-review {
  margin: 0 8px;
}
.question-review-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 6px 12px;
  padding: 12px 0;
  border-top: 1px solid var(--border);
  overflow-wrap: anywhere;
}
.question-review-item dt {
  color: var(--text-secondary);
  line-height: 1.5;
}
.question-review-item dd {
  grid-column: 1;
  display: grid;
  gap: 4px;
  margin: 0;
  white-space: pre-wrap;
  line-height: 1.5;
}
.question-review-item > .button {
  grid-column: 2;
  grid-row: 1 / 3;
  align-self: start;
}
.question-review-empty {
  color: var(--text-tertiary);
}
@media (hover: hover) {
  .question-choice:hover {
    background: var(--hover);
  }
}
@media (pointer: coarse) {
  .question-choice,
  .question-dock .button {
    min-height: 44px;
  }
  .question-input {
    font-size: 16px;
  }
}

sources.features/chat/permission-control.css:
