  padding-top: 4px;
  overflow: hidden;
}
.activity-tray-panel[hidden] {
  display: none;
}
.activity-tray-panel > ul {
  height: 100%;
  max-height: none;
}
.activity-tray-empty {
  margin: 0;
  padding: 12px 8px;
  color: var(--text-tertiary);
  font-size: 12px;
}
.activity-tray-error {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  color: var(--error);
  font-size: 12px;
}
@media (pointer: coarse) {
  .activity-tray-tab.button,
  .activity-tray-collapse.button {
    min-height: 44px;
  }
  .activity-tray-collapse.button {
    width: 44px;
    height: 44px;
  }
  .activity-tray-panel {
    height: calc(var(--activity-tray-rows) * 44px + 4px);
  }
