@media (max-width: 720px) {
  .composer-area > .activity-tray[data-active='true'] {
    margin-inline: 10px;
  }
}
.activity-tray-background.button {
  flex: none;
  min-height: 30px;
  padding-inline: 8px;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 500;
}

sources.features/chat/slash-commands.css:
