sources.features/tasks/tasks.css:
.tasks-page {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 18px;
  width: min(100%, 1440px);
  min-height: 0;
  margin: 0 auto;
  padding: 24px 24px 32px;
}
.tasks-note {
  color: var(--text-tertiary);
  font-size: 13px;
}

.tasks-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
}
.tasks-header h1 {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.tasks-summary {
  margin-top: 2px;
  color: var(--text-tertiary);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.tasks-filter {
  display: flex;
  align-items: center;
  gap: 8px;
}
.tasks-filter .select-trigger {
  width: 200px;
}
.task-select-project {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding-left: 4px;
}
.task-select-project .project-icon,
.task-project .project-icon {
  width: 14px;
  height: 14px;
  border-radius: 4px;
  font-size: 9.5px;
}
.tasks-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 8px 8px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  color: var(--text-secondary);
  font-size: 13px;
}

.task-columns {
  display: grid;
  flex: 1;
  grid-template-columns: repeat(4, minmax(232px, 1fr));
  align-items: start;
  gap: 12px;
  min-height: 0;
}
.task-column {
  --task-tint: var(--text-tertiary);
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  min-height: 160px;
  max-height: 100%;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface-under);
  transition: border-color var(--duration-fast) var(--ease-out);
}
.task-column[data-bucket='today'] {
  --task-tint: var(--warning);
}
.task-column[data-bucket='week'] {
  --task-tint: var(--project-blue);
}
.task-column[data-bucket='someday'] {
  --task-tint: var(--project-purple);
}
.task-column[data-bucket='done'] {
  --task-tint: var(--success);
}
.task-column[data-drop-target] {
  border-color: var(--border-heavy);
}
.task-column-header {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  padding: 0 2px 2px 6px;
}
.task-column-icon {
  flex: none;
  color: var(--task-tint);
}
.task-column-header h2 {
  font-size: 13px;
  font-weight: 600;
}
.task-count {
