  padding: 1px 6px;
  border-radius: 999px;
  background: var(--secondary);
  color: var(--text-tertiary);
  font-size: 11px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  text-align: center;
}
.task-column-header .button {
  margin-left: auto;
}

.task-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.task-slot {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.task-drop-line {
  height: 2px;
  margin: -2px 6px;
  border-radius: 2px;
  background: var(--task-tint);
}

.task-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: start;
  gap: 10px;
  padding: 10px 8px 10px 11px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--elevated);
  font-size: 13px;
  transition:
    border-color var(--duration-fast) var(--ease-out),
    opacity var(--duration-fast) var(--ease-out);
}
.task-card[draggable='true'] {
  cursor: grab;
}
.task-card[data-dragging] {
  opacity: 0.4;
}
.task-check {
  display: grid;
  flex: none;
  place-items: center;
  width: 17px;
  height: 17px;
  margin-top: 1px;
  padding: 0;
  border: 1.5px solid var(--border-heavy);
  border-radius: 50%;
  background: transparent;
  color: transparent;
  cursor: pointer;
  transition:
    background-color var(--duration-fast) var(--ease-out),
    border-color var(--duration-fast) var(--ease-out),
    color var(--duration-fast) var(--ease-out);
}
.task-check[aria-checked='true'] {
  border-color: var(--success);
  background: var(--success);
  color: var(--on-accent);
}
.task-body {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.task-title {
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text);
  font: inherit;
  line-height: 1.45;
  text-align: left;
  overflow-wrap: anywhere;
  cursor: text;
}
.task-notes {
  /* The first few lines; open the editor for the rest. */
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 12.5px;
  line-height: 1.45;
  overflow-wrap: anywhere;
  cursor: text;
}
.task-notes.markdown > * + * {
  margin-top: 4px;
}
.task-notes.markdown h1,
.task-notes.markdown h2,
.task-notes.markdown h3,
.task-notes.markdown h4 {
  margin: 0;
  font-size: inherit;
}
.task-notes.markdown ul,
.task-notes.markdown ol {
  padding-left: 16px;
}
.task-notes.markdown li + li {
  margin-top: 2px;
}
.task-notes.markdown pre {
  margin: 0;
  padding: 4px 6px;
  font-size: 11.5px;
}
.task-notes.markdown a {
  display: inline-block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  vertical-align: bottom;
}
.task-notes img {
  display: none;
}
.task-card[data-done] .task-notes {
  color: var(--text-tertiary);
}
.task-card[data-done] .task-title {
  color: var(--text-tertiary);
  text-decoration: line-through;
  text-decoration-color: var(--border-heavy);
}
.task-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}
.task-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  max-width: 100%;
  height: 20px;
  padding: 0 7px;
  border: 0;
  border-radius: 6px;
  background: var(--secondary);
  color: var(--text-secondary);
  font: inherit;
  font-size: 11.5px;
  white-space: nowrap;
}
.task-chip[data-tone='warning'] {
  background: color-mix(in srgb, var(--warning) 14%, transparent);
  color: var(--warning);
}
.task-link {
  cursor: pointer;
}
.task-start {
  background: color-mix(in srgb, var(--project-purple) 18%, transparent);
  color: color-mix(in srgb, var(--project-purple) 60%, var(--text));
  font-weight: 550;
  cursor: pointer;
}
.task-start:disabled {
  background: var(--secondary);
  color: var(--text-tertiary);
  font-weight: inherit;
  cursor: default;
}
.task-agent {
  color: color-mix(in srgb, var(--project-purple) 60%, var(--text));
}
.task-icon {
  justify-content: center;
  width: 22px;
  padding: 0;
}
.task-assignee[data-agent] {
  background: color-mix(in srgb, var(--project-purple) 18%, transparent);
  color: color-mix(in srgb, var(--project-purple) 60%, var(--text));
}
.task-delete {
  width: 24px;
  height: 24px;
  margin: -2px 0 -4px;
  opacity: 0;
}
.task-card:focus-within .task-delete {
  opacity: 1;
}

.task-empty {
  padding: 14px 8px 6px;
  color: var(--text-tertiary);
  font-size: 12.5px;
  text-align: center;
}
.task-add {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text-tertiary);
  font-size: 13px;
  text-align: left;
}
.task-new {
  align-items: center;
  grid-template-columns: auto minmax(0, 1fr);
  border-color: var(--border-heavy);
}
.task-new input,
.task-editor-title,
.task-editor-notes {
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text);
  font: inherit;
  outline: none;
}
.task-new .task-check {
  cursor: default;
}

.task-editor {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  border-color: var(--border-heavy);
  box-shadow: var(--card-shadow);
  cursor: auto;
}
.task-editor-title {
  font-weight: 500;
}
.task-editor-notes {
  field-sizing: content;
  min-height: 56px;
  max-height: 320px;
  color: var(--text-secondary);
  line-height: 1.45;
  resize: vertical;
}
.task-editor-fields {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.task-editor-fields .select {
  flex: 1 1 120px;
  min-width: 0;
}
.task-editor-fields .select-trigger {
  width: 100%;
  height: 28px;
  padding-left: 8px;
  font-size: 12px;
}
.task-editor-fields .select-menu[popover] {
  left: anchor(left);
  right: auto;
  min-width: anchor-size(width);
}
.task-editor-actions {
  display: flex;
  justify-content: flex-end;
  gap: 4px;
}
.task-editor-delete {
  margin-right: auto;
  color: var(--error);
}

.tasks-setup {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  max-width: 440px;
  margin: 12vh auto 0;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.5;
  text-align: center;
}
.tasks-setup-icon {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--glaze);
  box-shadow: var(--glaze-shadow);
  color: var(--text);
}
.tasks-setup h1 {
  color: var(--text);
  font-size: 20px;
  font-weight: 600;
}
.tasks-setup code {
  color: var(--text-tertiary);
  font-size: 12px;
  overflow-wrap: anywhere;
}

@media (hover: hover) {
  .task-card:hover {
    border-color: var(--border-heavy);
  }
  .task-card:hover .task-delete {
    opacity: 1;
  }
  .task-check:hover:not([aria-checked='true']) {
    border-color: var(--success);
    color: var(--success);
  }
  .task-start:hover:not(:disabled) {
    background: color-mix(in srgb, var(--project-purple) 28%, transparent);
  }
  .task-add:hover,
  .task-link:hover {
    background: var(--hover);
    color: var(--text-secondary);
  }
}
@media (pointer: coarse) {
  .task-delete {
    opacity: 1;
  }
}
@media (max-width: 1100px) {
  .task-columns {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 720px) {
  .tasks-page {
    padding: 16px 12px 24px;
  }
  .tasks-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .tasks-filter {
    flex-wrap: wrap;
  }
  .task-columns {
    grid-template-columns: minmax(0, 1fr);
  }
  .task-new input,
  .task-editor-title,
  .task-editor-notes {
    font-size: 16px;
  }
}

sources.features/terminal/terminal.css:
.terminal-panel,
.terminal-tabpanel {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.terminal-add {
  align-self: center;
  flex: none;
  margin-inline: 6px;
}
.terminal-tabs .wb-document-tab > button:hover {
  background: transparent;
}
.terminal-toolbar {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 12px;
  color: var(--text-tertiary);
  font-size: 11px;
}
.terminal-toolbar > [role='status'] {
  flex: none;
}
.terminal-viewport {
  flex: 1;
  min-width: 0;
  min-height: 0;
  margin: 4px 10px 10px;
  overflow: hidden;
  text-align: left;
  /* Ghostty draws the cursor on canvas; its editable host must not draw a second caret. */
  caret-color: transparent;
}
.terminal-error {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  color: var(--error);
}
.terminal-exited {
  color: var(--text-tertiary);
  font-size: 10px;
}
@media (pointer: coarse) {
  .terminal-add,
  .wb-document-tab > button {
    min-width: 44px;
    min-height: 44px;
  }
}

sources.features/terminal/terminal-drawer.css:
.workbench.terminal-drawer {
  width: 100%;
  min-width: 0;
  max-width: none;
  max-height: 60%;
  border-left: 0;
  border-top: 1px solid var(--border);
}
.terminal-resize {
  position: absolute;
  inset: -4px 0 auto;
  height: 8px;
  cursor: row-resize;
  touch-action: none;
  z-index: 4;
}
.terminal-resize:focus-visible {
  background: var(--accent-soft);
}
:root[data-platform] .terminal-drawer .wb-header {
  -webkit-app-region: no-drag;
}

sources.features/apps/apps.css:
.apps-page {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}
.apps-note {
  padding: 24px;
  color: var(--text-tertiary);
  font-size: 13px;
}
.apps-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  max-width: 440px;
  margin: 18vh auto 0;
  padding: 0 24px;
  color: var(--text-tertiary);
  text-align: center;
}
.apps-empty h2 {
  color: var(--text);
  font-size: 15px;
  font-weight: 600;
}
.apps-empty p {
  font-size: 13px;
  line-height: 1.5;
}

.apps-detail {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}
.apps-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 20px 12px;
  border-bottom: 1px solid var(--border);
}
.apps-header-text {
  flex: 1;
  min-width: 0;
}
.apps-header h1 {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.3;
}
.apps-header-meta {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
  color: var(--text-tertiary);
  font-size: 12px;
}
.apps-error-icon {
  color: var(--error);
}
.apps-spin {
  animation: apps-spin 1s linear infinite;
}
@keyframes apps-spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .apps-spin {
    animation: none;
  }
}

.apps-runs {
  flex: none;
  border-top: 1px solid var(--border);
}
.apps-runs[data-open='true'] {
  display: flex;
  flex-direction: column;
  max-height: 40%;
}
.apps-runs-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  height: 34px;
  padding: 0 20px;
  color: var(--text-secondary);
  font-size: 12.5px;
  font-weight: 550;
}
.apps-runs-toggle:hover {
  color: var(--text);
}
.apps-runs-count {
  color: var(--text-tertiary);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}
.apps-runs-list {
  overflow: auto;
  padding: 0 12px 10px;
}
.apps-run-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 5px 8px;
  border-radius: 6px;
  font-size: 12.5px;
  text-align: left;
}
.apps-run-summary:disabled {
  opacity: 1;
  color: inherit;
  cursor: default;
}
.apps-run-summary:not(:disabled):hover {
  background: var(--hover);
}
.apps-run-dot {
  width: 6px;
  height: 6px;
  flex: none;
  border-radius: 50%;
  background: var(--text-tertiary);
}
.apps-run[data-status='ok'] .apps-run-dot {
  background: var(--success);
}
.apps-run[data-status='error'] .apps-run-dot {
  background: var(--error);
}
.apps-run[data-status='running'] .apps-run-dot {
  background: var(--warning);
}
.apps-run-fn {
  font-family: var(--font-mono);
  font-size: 12px;
}
.apps-run-meta {
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
}
.apps-run-detail {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 2px 8px 8px 22px;
}
.apps-run-session {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  color: var(--text-secondary);
  font-size: 12.5px;
  text-align: left;
}
.apps-run-session:hover {
  color: var(--text);
}
.apps-run-error,
.apps-run-logs {
  max-height: 220px;
  overflow: auto;
  padding: 8px 10px;
  border-radius: 6px;
  background: var(--code-bg);
  font-family: var(--font-mono);
  font-size: 11.5px;
  line-height: 1.5;
  white-space: pre-wrap;
}
.apps-run-error {
  color: var(--error);
}

.apps-index {
  overflow-y: auto;
  padding: 24px 24px 32px;
}
.apps-index-header {
  max-width: 1080px;
  margin: 0 auto 16px;
}
.apps-index-header h1 {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.apps-index-header p {
  margin-top: 2px;
  color: var(--text-tertiary);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.apps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 12px;
  max-width: 1080px;
  margin: 0 auto;
}
.apps-tile {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  width: 100%;
  min-width: 0;
  padding: 14px;
  border: 0;
  border-radius: 14px;
  background: var(--glaze);
  box-shadow: var(--glaze-shadow);
  color: var(--text);
  text-align: left;
}
.apps-tile-text {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
.apps-tile-title {
  font-size: 13.5px;
  font-weight: 550;
  line-height: 1.35;
}
.apps-tile-meta {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--text-secondary);
  font-size: 12.5px;
}
.apps-tile[data-state='error'] .apps-tile-meta {
  color: var(--error);
}
.apps-tile-foot {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 4px;
  color: var(--text-tertiary);
  font-size: 12px;
}
.apps-tile-foot .apps-project {
  margin-left: auto;
}
@media (hover: hover) {
  .apps-tile:hover {
    box-shadow:
      var(--glaze-shadow),
      0 0 0 1px var(--border-heavy);
  }
}

.apps-code {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}
.apps-code-files {
  display: flex;
  flex: none;
  gap: 2px;
  overflow-x: auto;
  padding: 6px 12px;
  border-bottom: 1px solid var(--border);
}
.apps-code-files button {
  flex: none;
  height: 26px;
  padding: 0 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 12px;
}
.apps-code-files button[aria-selected='true'] {
  background: var(--selected);
  color: var(--text);
}
@media (hover: hover) {
  .apps-code-files button:hover:not([aria-selected='true']) {
    background: var(--hover);
  }
}

.app-icon {
  border-radius: 27%;
}
.app-icon svg {
  display: block;
}
.apps-project {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}
.apps-project .project-icon {
  width: 14px;
  height: 14px;
  border-radius: 4px;
  font-size: 9.5px;
}

.apps-meta-link {
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  white-space: nowrap;
  cursor: pointer;
}
.apps-meta-link:hover,
.apps-meta-link:focus-visible {
  color: var(--text-secondary);
  text-decoration: underline;
  text-underline-offset: 2px;
}
/* The model picker opens below its trigger, past the dialog's edge. */
.dialog.apps-model-dialog {
  overflow: visible;
}
.apps-model {
  display: flex;
  margin: 12px 0;
}
.apps-model .composer-controls {
  flex: 0 1 auto;
  justify-content: flex-start;
}
.apps-model-note {
  color: var(--text-secondary);
  font-size: 13px;
}
.apps-model-note + .dialog-actions,
.text-error + .dialog-actions {
  margin-top: 16px;
}
.apps-run-calls {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 12px;
}
.apps-run-calls li {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}
.apps-run-call-kind {
  font-family: var(--font-mono);
  color: var(--text-secondary);
}
.apps-run-call-meta {
  margin-left: auto;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.apps-run-call-error {
  flex-basis: 100%;
  color: var(--error);
}

.apps-icon-button {
  display: grid;
  flex: none;
  padding: 0;
  border: 0;
  border-radius: 9px;
  background: none;
  place-items: center;
}
.apps-icon-button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
@media (hover: hover) {
  .apps-icon-button:hover .app-icon {
    filter: brightness(1.12);
  }
}
.apps-icon-picker {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 20px;
}
.apps-icon-preview {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  font-weight: 550;
}
.apps-icon-search {
  width: 100%;
  height: 32px;
  margin-bottom: 8px;
  padding: 0 10px;
  border: 0;
  border-radius: 8px;
  background: var(--well);
  box-shadow:
    var(--well-shadow),
    inset 0 0 0 1px var(--border);
  color: var(--text);
  font-size: 13px;
}
.apps-icon-search:focus {
  outline: none;
  box-shadow:
    var(--well-shadow),
    inset 0 0 0 1px var(--border-heavy);
}
.apps-icon-scroll {
  display: flex;
  flex-direction: column;
  gap: 10px;
  height: 260px;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.apps-icon-scroll .apps-note {
  padding: 8px 0;
}
.apps-icon-group {
  margin-bottom: 4px;
  color: var(--text-tertiary);
  font-size: 11.5px;
  font-weight: 550;
}
.apps-icon-glyphs {
  display: grid;
  grid-template-columns: repeat(auto-fill, 36px);
  gap: 4px;
  color: var(--text-secondary);
}
.apps-icon-glyphs .project-color-option:has(input:checked) {
  color: var(--text);
}

.apps-settings {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 16px;
  min-height: 0;
  overflow-y: auto;
  padding: 24px 24px 48px;
}
.apps-settings > .settings-group {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
}
.apps-settings .apps-project {
  font-size: 13px;
}

sources.features/find/find.css:
.find-bar {
  display: flex;
  align-items: center;
  gap: 2px;
  width: min(340px, calc(100% - 24px));
  height: 38px;
  padding: 0 4px 0 12px;
  border: 1px solid var(--border-heavy);
  border-radius: 10px;
  background: var(--elevated);
  box-shadow: var(--shadow);
  /* Hosts like CodeMirror's panel set their own text color; the bar keeps the app's. */
  color: var(--text);
}
/* Class-qualified so host panels' field styles (the workspace panel's input ring) never apply. */
.find-bar .find-input {
  flex: 1;
  height: auto;
  min-width: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  outline: none;
  background: transparent;
  box-shadow: none;
  font-size: 13px;
}
.find-bar .find-input::placeholder {
  color: var(--text-tertiary);
}
.find-bar .button-icon {
  width: 26px;
  height: 26px;
}
.find-count {
  padding-inline: 4px;
  color: var(--text-tertiary);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.find-count[data-empty] {
  color: var(--error);
}
/* Floats over a scrolling surface without shifting its content. */
.find-overlay {
  position: absolute;
  top: 10px;
  right: 12px;
  left: 12px;
  z-index: 20;
  display: flex;
  justify-content: flex-end;
  pointer-events: none;
}
/* The same float placed as a scroller's first child, so it needs no positioned wrapper. */
.find-sticky {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  justify-content: flex-end;
  height: 0;
  pointer-events: none;
}
.find-sticky > .find-bar {
  margin: 10px 12px 0 0;
}
.find-overlay > .find-bar,
.find-sticky > .find-bar {
  flex-shrink: 0;
  pointer-events: auto;
}
/* CodeMirror panel host: the bar floats over the code instead of pushing it down. */
.cm-find-panel {
  position: absolute;
  top: 8px;
  right: 12px;
  z-index: 5;
  display: flex;
  justify-content: flex-end;
  width: calc(100% - 24px);
  pointer-events: none;
}
.cm-find-panel > .find-bar {
  pointer-events: auto;
}
::highlight(find-match) {
  background: color-mix(in srgb, var(--warning) 30%, transparent);
}
::highlight(find-active) {
  background: color-mix(in srgb, var(--warning) 70%, transparent);
}

