sources.features/sessions/session-row.css:
.session-entry-row {
  display: flex;
  align-items: center;
  border-radius: 6px;
}
.session-entry-row .session-row {
  flex: 1;
  min-width: 0;
}
.session-shortcut {
  position: absolute;
  left: 8px;
  top: 50%;
  transform: translateY(-50%);
  display: grid;
  place-items: center;
  width: 16px;
  height: 16px;
  border: 1px solid var(--border-heavy);
  border-radius: 4px;
  background: var(--elevated);
  color: var(--text-secondary);
  font: inherit;
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  visibility: hidden;
  pointer-events: none;
}
:root[data-thread-shortcuts] .session-shortcut {
  visibility: visible;
}
:root[data-thread-shortcuts] .session-row:has(.session-shortcut) > .session-project,
:root[data-thread-shortcuts] .session-row:has(.session-shortcut) > .session-check {
  visibility: hidden;
}
.session-entry[data-selected] .session-entry-row {
  background: var(--selected);
}
.session-entry[data-selected] .session-row {
  background: transparent;
}
.session-actions-menu,
.session-details {
  position: fixed;
  inset: auto;
  margin: 0;
  min-width: 180px;
  padding: 4px;
  border: 1px solid var(--border-heavy);
  border-radius: 8px;
  background: var(--elevated);
  color: var(--text);
  box-shadow: var(--shadow);
}
.session-details {
  width: max-content;
  min-width: 0;
  max-width: min(320px, calc(100vw - 16px));
  padding: 8px 10px;
  font-size: 12px;
  overflow-wrap: anywhere;
  pointer-events: none;
}
.session-details-time {
  margin-top: 4px;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
}
.session-actions-menu button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  width: 100%;
  min-height: 32px;
  padding: 6px 10px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  text-align: left;
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}
.session-actions-menu button:focus-visible {
  background: var(--hover);
}
.session-actions-menu kbd {
  flex: none;
  color: var(--text-tertiary);
  font-family: inherit;
  font-size: 12px;
}
.session-actions-menu button:disabled {
  color: var(--text-tertiary);
  cursor: default;
}
.session-actions-menu {
  max-width: min(280px, calc(100vw - 16px));
  -webkit-app-region: no-drag;
}
.session-actions-error {
  padding: 6px 10px;
  color: var(--error);
  font-size: 12px;
  overflow-wrap: anywhere;
}
.session-actions-toggle {
  display: flex;
  flex-shrink: 0;
  -webkit-app-region: no-drag;
}
.session-actions-toggle .button[aria-expanded='true'] {
  background: var(--selected);
  color: var(--text);
}
.session-unread[data-responding] {
  position: absolute;
  right: 8px;
  top: calc(50% + 2px);
  width: 4px;
  height: 4px;
}
@media (pointer: coarse) {
  .session-actions-menu button {
    min-height: 44px;
  }
}

sources.features/sessions/session-title.css:
