sources.features/browser/browser.css:
/* Pages are fixed overlays; the host never takes a place in the app grid. */
.browser-host {
  display: contents;
}
.browser-view {
  position: fixed;
  top: 0;
  left: -100000px;
  /* Above an expanded workbench; popovers and dialogs use the top layer. */
  z-index: 6;
  width: 800px;
  height: 600px;
  overflow: hidden;
  background: var(--surface);
}
.browser-view webview {
  width: 100%;
  height: 100%;
}
/* Keep dragging the workbench edge smooth when the pointer crosses a page. */
:root:has(.workbench[data-resizing]) .browser-view {
  pointer-events: none;
}
.browser-panel {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.browser-toolbar {
  gap: 2px;
}
.browser-toolbar .button[aria-pressed='true'] {
  background: var(--selected);
  color: var(--text);
}
.browser-address {
  display: flex;
  flex: 1;
  min-width: 0;
  margin-inline: 4px;
}
.browser-address input {
  flex: 1;
  width: 100%;
}
.browser-slot {
  position: relative;
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.browser-tab-title {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.browser-tabs .wb-document-tab > button:hover {
  background: transparent;
}
.browser-add {
  align-self: center;
  flex: none;
  margin-inline: 6px;
}
@media (pointer: coarse) {
  .browser-add {
    min-width: 44px;
    min-height: 44px;
  }
}
.browser-error-url {
  overflow-wrap: anywhere;
  color: var(--text-tertiary);
  font-size: 12px;
}
.browser-error-actions {
  display: flex;
  justify-content: center;
  gap: 8px;
}

sources.features/session-panel/session-panel.css:
.toolbar-session-actions {
  flex-shrink: 0;
  margin-left: auto;
}
.toolbar-status + .toolbar-session-actions {
  margin-left: 0;
}
.session-panel-toggle {
  flex-shrink: 0;
}
.session-panel-toggle ~ .workspace-panel-toggle {
  position: relative;
  margin-left: 4px;
}
.session-panel-toggle ~ .workspace-panel-toggle::before {
  content: '';
  position: absolute;
  top: 8px;
  bottom: 8px;
  left: -6px;
  border-left: 1px solid var(--border-heavy);
}
.session-panel-toggle[aria-expanded='true'] {
  background: var(--selected);
  color: var(--text);
}
.session-panel {
  position: fixed;
  inset: calc(var(--toolbar-height) + 16px) 16px auto auto;
  position-anchor: --chat-toolbar;
  top: calc(anchor(bottom) + 8px);
  right: calc(anchor(right) + 12px);
  width: min(288px, calc(100vw - 32px));
  max-width: calc(anchor-size(width) - 24px);
  max-height: calc(100dvh - var(--toolbar-height) - 32px);
  margin: 0;
  padding: 0 12px;
  overflow-y: auto;
  overscroll-behavior: contain;
  border: 1px solid var(--border-heavy);
  border-radius: 12px;
  background: var(--surface);
  color: var(--text);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  -webkit-app-region: no-drag;
}
.chat-column {
  position: relative;
}
.session-panel[data-layout='inline'] {
  position: absolute;
  z-index: 2;
  position-anchor: auto;
  inset: calc(var(--toolbar-height) + 16px) 16px auto auto;
  width: var(--session-card-width, 288px);
  max-width: none;
  max-height: calc(100% - var(--toolbar-height) - 32px);
}
.session-panel-heading,
.session-panel-row,
.session-panel-details > summary {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.session-panel-heading {
  justify-content: space-between;
  padding-top: 6px;
}
.session-panel-heading h2 {
  font-size: 13px;
}
.session-panel h2,
.session-panel h3 {
  font-size: inherit;
  font-weight: 600;
}
.session-panel-row {
  justify-content: space-between;
}
.session-panel-row > .truncate {
  min-width: 0;
}
.session-panel-row > svg,
.session-panel-details > summary > svg {
  flex-shrink: 0;
  color: var(--text-secondary);
}
.session-panel-section {
  padding-block: 8px;
}
.session-panel-section + .session-panel-section {
  border-top: 1px solid var(--border);
}
.session-panel-row > span,
.session-project-row {
  color: var(--text-secondary);
}
.session-context {
  padding-top: 4px;
}
.session-context-meter {
  display: block;
  appearance: none;
  width: 100%;
  height: 4px;
  margin-block: 8px;
  border: 0;
  border-radius: 4px;
  overflow: hidden;
  background: var(--secondary-hover);
  color: var(--success);
}
.session-context-meter::-webkit-progress-bar {
  background: var(--secondary-hover);
}
.session-context-meter::-webkit-progress-value {
  border-radius: 4px;
  background: var(--success);
}
.session-context-meter::-moz-progress-bar {
  border-radius: 4px;
  background: var(--success);
}
.session-panel-note {
  color: var(--text-tertiary);
  font-size: 12px;
  overflow-wrap: anywhere;
}
.session-project-row {
  margin-top: 6px;
}
.session-project-heading {
  justify-content: flex-start;
}
.session-project-row > span {
  flex: 1;
}
.session-file-totals {
  white-space: nowrap;
}
.session-panel-link {
  width: 100%;
  padding: 4px 0;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
}
.session-panel-link:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}
.session-panel-link .session-panel-link-title {
  color: var(--text);
  font-weight: 600;
}
.session-subagents-link {
  justify-content: flex-start;
}
.session-subagents-preview {
  display: flex;
  flex: none;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  color: var(--text-secondary);
}
.session-subagent-avatar {
  display: inline-flex;
}
.session-subagent-avatar:nth-child(3n + 1) {
  color: var(--project-pink);
}
.session-subagent-avatar:nth-child(3n + 2) {
  color: var(--project-orange);
}
.session-subagent-avatar:nth-child(3n) {
  color: var(--project-purple);
}
.session-subagents-more {
  color: var(--text-tertiary);
  font-size: 12px;
}
.session-additions,
.session-resource-status[data-connected='true'] {
  color: var(--success);
}
.session-panel-details > summary {
  min-height: 20px;
  cursor: pointer;
  list-style: none;
  border-radius: 4px;
}
.session-panel-details > summary::-webkit-details-marker {
  display: none;
}
.session-panel-details[open] > summary .session-details-chevron {
  transform: rotate(90deg);
}
.session-details-value {
  margin-left: auto;
  color: var(--text-secondary);
  white-space: nowrap;
}
.session-details-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding-top: 14px;
}
.session-stat-list {
  display: grid;
  gap: 6px;
}
.session-stat-list > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.session-stat-list dt {
  font-weight: 500;
}
.session-stat-list dd {
  margin: 0;
  color: var(--text-secondary);
}
.session-resource-list {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: 240px;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.session-resource-list > li + li {
  border-top: 1px solid var(--border);
  margin-top: 10px;
  padding-top: 10px;
}
.session-resource-status {
  text-transform: capitalize;
  white-space: nowrap;
}
.session-panel-error {
  color: var(--error);
  overflow-wrap: anywhere;
  font-size: 12px;
}
@media (hover: hover) {
  .session-panel-details > summary:hover {
    color: var(--text-secondary);
  }
}
@media (max-width: 720px) {
  .session-panel {
    font-size: 16px;
    width: min(320px, calc(100vw - 32px));
  }
  .session-panel-details > summary {
    min-height: 44px;
  }
  .session-panel-link,
  .session-actions-toggle .button {
    min-height: 44px;
  }
  .session-actions-toggle .button {
    min-width: 44px;
  }
  .session-panel-heading .button,
  .session-panel-toggle {
    min-width: 44px;
    min-height: 44px;
  }
}
.session-canvas-list > li + li {
  margin-top: 2px;
  padding-top: 2px;
  border-top: 0;
}
.session-canvas-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  padding: 5px 8px;
  border: 0;
  border-radius: 7px;
  background: none;
  color: var(--text);
  text-align: left;
}
.session-canvas-link:hover {
  background: var(--hover);
}
.session-canvas-link > svg {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

sources.features/threads/threads.css:
/* The view switch shows state, so it stays visible unlike hover-only heading actions. */
/* Square and in the same column as the search and project action buttons. */
.sidebar-heading .button.thread-view-toggle {
  width: 28px;
  height: 28px;
  min-height: 28px;
  margin-right: -2px;
  padding: 0;
  color: var(--text-tertiary);
  opacity: 1;
}
/* Keep the heading's 28px buttons from touching the first row below. */
.thread-section > .sidebar-heading,
.project-list > .sidebar-heading {
  margin-bottom: 6px;
}
.sidebar-heading-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-right: -2px;
}
.sidebar-heading-actions .button.thread-view-toggle {
  margin-right: 0;
}
.project-filter-trigger {
  anchor-name: --project-filter;
}
.project-filter {
  position: fixed;
  position-anchor: --project-filter;
  top: anchor(bottom);
  right: anchor(right);
  inset-inline-start: auto;
  bottom: auto;
  width: 220px;
  max-height: min(360px, calc(100vh - 80px));
  margin: 4px 0 0;
  padding: 4px;
  overflow-y: auto;
  border: 1px solid var(--border-heavy);
  border-radius: 8px;
  background: var(--elevated);
  color: var(--text);
  box-shadow: var(--shadow);
  font-size: 13px;
}
.project-filter-heading,
.project-filter-empty {
  padding: 6px 8px 4px;
  color: var(--text-tertiary);
  font-size: 12px;
  font-weight: 500;
}
.project-filter button {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 30px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
}
.project-filter button > .truncate {
  flex: 1;
}
.project-filter button[aria-checked='false'] {
  color: var(--text-tertiary);
}
.project-filter button > .project-icon {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  font-size: 10px;
}
.project-filter button[aria-checked='false'] > .project-icon {
  opacity: 0.5;
}
.project-filter .project-filter-reset {
  margin-top: 4px;
  border-top: 1px solid var(--border);
  border-radius: 0 0 6px 6px;
  color: var(--text-secondary);
}
.project-filter button:focus-visible {
  background: var(--hover);
  outline: none;
}
@media (hover: hover) {
  .project-filter button:hover {
    background: var(--hover);
  }
}
.sidebar-heading .button.thread-view-toggle[aria-pressed='true'] {
  background: var(--selected);
  color: var(--text);
}
.thread-section {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding-bottom: 14px;
}
/* Cross-project rows are not nested under a folder, so they start at the row edge. */
.thread-section .session-row,
.thread-section .session-more,
.thread-section .sidebar-note {
  padding-left: 8px;
}
.session-project {
  display: grid;
  flex: none;
  place-items: center;
}
.session-project > .project-icon {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  font-size: 10px;
}
.session-attention {
  display: grid;
  flex: none;
  place-items: center;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}
.session-attention[data-kind='permission'] {
  background: var(--warning);
  color: var(--surface);
}
.session-attention[data-kind='question'] {
  background: var(--accent);
  color: var(--on-accent);
}
.session-check {
  display: grid;
  flex: none;
  place-items: center;
  width: 16px;
  height: 16px;
  border: 1px solid var(--border-heavy);
  border-radius: 4px;
}
.session-entry[data-checked] .session-check {
  border-color: transparent;
  background: var(--accent);
  color: var(--on-accent);
}
/* While selecting, highlight the chosen rows rather than the open thread. */
[data-picking] .session-entry[data-selected]:not([data-checked]) .session-entry-row {
  background: transparent;
}
[data-picking] .session-entry[data-checked] .session-entry-row {
  background: var(--selected);
}
.thread-section-toggle {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
}
.thread-undo {
  display: flex;
  flex: none;
  align-items: center;
  gap: 2px;
  margin-top: 8px;
  padding: 2px 2px 2px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--elevated);
  color: var(--text-secondary);
  font-size: 12px;
}
.thread-undo > span {
  flex: 1;
}
.thread-undo .button-icon {
  width: 24px;
  min-height: 24px;
}
@media (hover: hover) {
  .thread-section-toggle:hover {
    color: var(--text);
  }
}

.thread-pin {
  position: relative;
}
.thread-pin[data-dragging] {
  opacity: 0.4;
}
.thread-pin[data-drop]::before {
  position: absolute;
  right: 6px;
  left: 6px;
  height: 2px;
  border-radius: 2px;
  background: var(--accent);
  content: '';
  pointer-events: none;
}
.thread-pin[data-drop='before']::before {
  top: -1px;
}
.thread-pin[data-drop='after']::before {
  bottom: -2px;
}

sources.features/canvas/canvas.css:
.canvas-card {
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(100%, 440px);
  margin: 14px 0;
  padding: 10px 14px 10px 10px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--elevated);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  container: canvas-card / inline-size;
  transition:
    background-color var(--duration-fast) var(--ease-out),
    border-color var(--duration-fast) var(--ease-out);
}
.canvas-card:disabled {
  cursor: default;
}
.canvas-card .app-icon {
  flex: none;
  border-radius: 27%;
}
.canvas-card-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}
.canvas-card-title {
  font-size: 14px;
  font-weight: 550;
  line-height: 1.35;
}
.canvas-card-detail {
  color: var(--text-tertiary);
  font-size: 12.5px;
  line-height: 1.35;
}
.canvas-card-detail[data-error] {
  color: var(--error);
}
.canvas-card-open {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 4px;
  color: var(--text-secondary);
  font-size: 12.5px;
  font-weight: 550;
}
/* In a narrow chat column the title keeps the room; the arrow alone says it opens. */
@container canvas-card (max-width: 360px) {
  .canvas-card-label {
    display: none;
  }
}
@media (hover: hover) {
  .canvas-card:not(:disabled):hover {
    border-color: var(--border-heavy);
    background: var(--hover);
  }
  .canvas-card:not(:disabled):hover .canvas-card-open {
    color: var(--text);
  }
}
.canvas-frame {
  position: relative;
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}
.canvas-frame iframe {
  display: block;
  width: 100%;
  border: 0;
  /* The frame adopts this element's color-scheme, so its background stays transparent. */
  background: transparent;
}
.canvas-frame iframe {
  /* Fills the panel. */
  flex: 1;
  min-height: 0;
}
.canvas-frame-error {
  max-height: 160px;
  overflow: auto;
  margin-bottom: 8px;
  padding: 8px 12px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--error) 10%, transparent);
  color: var(--error);
  font-family: var(--font-mono);
  font-size: 12px;
  white-space: pre-wrap;
}
.canvas-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}
.canvas-tabs .wb-document-tab > button:hover {
  background: transparent;
}
.canvas-add,
.canvas-comment {
  align-self: center;
  flex: none;
  margin-inline: 6px;
}
.canvas-comment {
  margin-inline-end: 0;
}
.canvas-add[aria-pressed='true'],
.canvas-comment[aria-pressed='true'] {
  background: var(--glaze);
  box-shadow: var(--glaze-shadow);
  color: var(--text);
}
.canvas-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 8px;
}
.canvas-list ul {
  margin: 0;
  padding: 0;
  list-style: none;
}
.canvas-list-item {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-right: 6px;
  border-radius: 8px;
}
.canvas-list-item:hover {
  background: var(--hover);
}
.canvas-list-item > .button {
  opacity: 0;
}
.canvas-list-item:hover > .button,
.canvas-list-item > .button:focus-visible {
  opacity: 1;
}
.canvas-list-open {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 8px 10px;
  border: 0;
  background: none;
  color: var(--text-secondary);
  text-align: left;
}
.canvas-list-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.canvas-list-title {
  color: var(--text);
}
.canvas-list-meta {
  color: var(--text-tertiary);
  font-size: 12px;
}

